#!/usr/bin/env python3
"""Kernel de Kaggle: CANASTA-GLOBAL, tanda 3 de 6 (docs/research/canasta_global_20261108/PREREGISTRO.md). Procesa sus cubos
y guarda CANASTA_PARTE.pkl; la combinación con el nulo completo se hace al juntar todas las tandas."""
import glob, json, pickle, sys, time
from pathlib import Path
import numpy as np
MODULOS = {"edgelab/research/canasta_global.py": "\"\"\"CANASTA-GLOBAL (2026-11-08, regla global de Nico, docs/DECISIONES_20261108.md): canasta de reglas estables, poco correlacionadas\ny de varios activos elegida entre TODAS las celdas de los 106 cubos, con el nulo que repite la selecci\u00f3n completa.\nPre-registro: docs/research/canasta_global_20261108/PREREGISTRO.md. Mismo criterio que `tools/canasta_orb.py`, en flujo.\n\nPor cubo (uno por vez): matriz diaria por bloque (sesiones del bloque \u00d7 celdas con >= MIN_OPS operaciones en la ventana) y, para las\nB+1 series de signos (fila 0 = observado), sumas por bloque con un producto matricial. Una celda es estable si su media es > 0 en al\nmenos 4 de los 5 bloques y su t diario (sobre todas las sesiones de la ventana, 0 los d\u00edas sin operar) es > 1. Se guardan las\nTOP_POR_CUBO estables de mayor t de cada r\u00e9plica y, en una segunda pasada, sus series diarias. Despu\u00e9s, por r\u00e9plica: orden por t,\ncorrelaci\u00f3n < 0,3 con las ya elegidas, como m\u00e1ximo 3 por cubo, hasta 10, al menos 3 instrumentos; estad\u00edstico = t de la canasta.\n\"\"\"\nfrom __future__ import annotations\n\nimport numpy as np\n\nfrom edgelab.research import grilla_masiva as GM\n\nVENTANA = (20250805, 20260930)\nN_BLOQUES, MIN_POS, T_MIN, CORR_MAX, MAX_REGLAS, MAX_POR_CUBO, MIN_INST, TOP_POR_CUBO, MIN_OPS = 5, 4, 1.0, 0.3, 10, 3, 3, 20, 30\n\n\ndef _dia_cubo(cubo, dias):\n    \"\"\"Iterador (posici\u00f3n global del d\u00eda, R por celda evaluable) y el \u00edndice de celdas evaluables (>= MIN_OPS en la ventana).\"\"\"\n    m = (cubo.ses >= VENTANA[0]) & (cubo.ses <= VENTANA[1])\n    idx = [cubo.idx[m, j] for j in range(cubo.idx.shape[1])]; ses = cubo.ses[m]; net = cubo.net[m]\n    _, _, Ct = GM.tensor(cubo.perillas, idx, net); ev = np.flatnonzero(Ct.ravel() >= MIN_OPS)\n    orden = np.argsort(ses, kind=\"stable\"); so = ses[orden]; u = np.unique(so)\n    cortes = np.searchsorted(so, u, side=\"left\").tolist() + [len(so)]; pos = np.searchsorted(dias, u)\n\n    def it():\n        for q in range(len(u)):\n            o = orden[cortes[q]:cortes[q + 1]]\n            Sd, _, _ = GM.tensor(cubo.perillas, [ix[o] for ix in idx], net[o]); yield int(pos[q]), Sd.ravel()[ev]\n    return it, ev\n\n\ndef candidatos_cubo(cubo, dias, G):\n    \"\"\"Por r\u00e9plica b: \u00edndices (en ev) de las TOP_POR_CUBO estables de mayor t y sus t. G: (B+1, D) signos por d\u00eda global.\"\"\"\n    it, ev = _dia_cubo(cubo, dias); D = len(dias); E = len(ev); Bp = G.shape[0]\n    if E == 0: return ev, [np.zeros(0, np.int64)] * Bp, [np.zeros(0)] * Bp\n    bloque = np.minimum((np.arange(D) * N_BLOQUES) // D, N_BLOQUES - 1)\n    sumb = np.zeros((N_BLOQUES, Bp, E), np.float32); sq = np.zeros(E)\n    filas, buf = [], []\n    def vaciar():\n        if not filas: return\n        P = np.array(filas); S = np.stack(buf).astype(np.float32)\n        for k in np.unique(bloque[P]):\n            m = bloque[P] == k; sumb[k] += G[:, P[m]].astype(np.float32) @ S[m]\n        sq[:] += (S.astype(np.float64) ** 2).sum(0); filas.clear(); buf.clear()\n    for p, x in it():\n        filas.append(p); buf.append(x)\n        if len(filas) >= 40: vaciar()\n    vaciar()\n    tot = sumb.sum(0)                                                     # (B+1, E)\n    with np.errstate(invalid=\"ignore\", divide=\"ignore\"):\n        mu = tot / D; var = (sq[None, :] - D * mu ** 2) / (D - 1); t = mu / np.sqrt(var / D)\n    estable = ((sumb > 0).sum(0) >= MIN_POS) & (t > T_MIN) & np.isfinite(t)\n    top, tt = [], []\n    for b in range(Bp):\n        j = np.flatnonzero(estable[b])\n        j = j[np.argsort(-t[b, j])][:TOP_POR_CUBO]; top.append(j); tt.append(t[b, j])\n    return ev, top, tt\n\n\ndef series_cubo(cubo, dias, columnas):\n    \"\"\"Series diarias (D \u00d7 len(columnas)) sin signo de las celdas pedidas (\u00edndices en ev).\"\"\"\n    it, ev = _dia_cubo(cubo, dias); X = np.zeros((len(dias), len(columnas)), np.float32)\n    if len(columnas):\n        for p, x in it(): X[p] = x[columnas]\n    return X\n\n\ndef elegir(cands, series, G_b):\n    \"\"\"cands: lista de (t, cubo, instrumento, clave); series: clave -> serie sin signo; G_b: signos (D,). Devuelve (elegidas, t).\"\"\"\n    el, por_cubo, Xs = [], {}, []\n    for t, cu, inst, k in sorted(cands, key=lambda c: -c[0]):\n        if por_cubo.get(cu, 0) >= MAX_POR_CUBO: continue\n        x = series[k] * G_b\n        if any(abs(np.corrcoef(x, y)[0, 1]) >= CORR_MAX if np.std(x) > 0 and np.std(y) > 0 else False for y in Xs): continue\n        el.append((cu, inst, k)); Xs.append(x); por_cubo[cu] = por_cubo.get(cu, 0) + 1\n        if len(el) == MAX_REGLAS: break\n    if len({i for _, i, _ in el}) < MIN_INST: return [], 0.0\n    c = np.mean(Xs, axis=0); s = c.std(ddof=1)\n    return el, float(c.mean() / (s / np.sqrt(len(c)))) if s > 0 else 0.0\n\n\ndef signos(dias, B, seed=20261108):\n    rng = np.random.default_rng(seed); G = np.ones((B + 1, len(dias))); G[1:] = rng.choice([-1.0, 1.0], size=(B, len(dias)))\n    return G\n\n\ndef procesar(fuentes, dias, B=200, seed=20261108, log=None):\n    \"\"\"Una tanda de cubos (2026-11-08: en paralelo, una tanda por kernel). Devuelve lo necesario para combinar: candidatas por\n    r\u00e9plica y series diarias sin signo de su uni\u00f3n. Los d\u00edas y la semilla deben ser los mismos en todas las tandas.\"\"\"\n    G = signos(dias, B, seed); out = []\n    for n, (nombre, inst, f) in enumerate(fuentes):\n        cubo = f(); ev, top, tt = candidatos_cubo(cubo, dias, G)\n        union = np.unique(np.concatenate(top)) if any(len(x) for x in top) else np.zeros(0, np.int64)\n        out.append(dict(nombre=nombre, instrumento=inst, ev=ev[union] if len(union) else np.zeros(0, np.int64), union=union,\n                        series=series_cubo(cubo, dias, union), top=[np.searchsorted(union, x) for x in top], tt=tt,\n                        perillas=[q.nombre for q in cubo.perillas]))\n        if log: log(f\"cubo {n + 1}/{len(fuentes)} {nombre} evaluables {len(ev)} candidatas obs {len(top[0])}\")\n        del cubo\n    return out\n\n\ndef combinar(partes, dias, B=200, seed=20261108, completo=True):\n    \"\"\"Selecci\u00f3n global sobre las tandas disponibles. Con `completo=False` (tandas parciales) informa la canasta observada sin p.\"\"\"\n    G = signos(dias, B, seed); por_rep = [[] for _ in range(B + 1)]; series = {}; meta = {}\n    for c in partes:\n        for i in range(len(c[\"union\"])): series[(c[\"nombre\"], i)] = c[\"series\"][:, i].astype(float)\n        meta[c[\"nombre\"]] = c\n        for b in range(B + 1): por_rep[b] += [(float(tv), c[\"nombre\"], c[\"instrumento\"], (c[\"nombre\"], int(j))) for j, tv in zip(c[\"top\"][b], c[\"tt\"][b])]\n    obs, t_obs = elegir(por_rep[0], series, G[0])\n    if completo:\n        nul = [elegir(por_rep[b], series, G[b])[1] for b in range(1, B + 1)]\n        p = float((1 + sum(x >= t_obs for x in nul)) / (B + 1)) if obs else 1.0; q = np.quantile(nul, [.5, .9, .95]).tolist()\n    else: p, q = None, None\n    reglas = []\n    for cu, inst, (nm, j) in obs:\n        x = series[(nm, j)]\n        reglas.append(dict(cubo=nm, instrumento=inst, celda_plana=int(meta[nm][\"ev\"][j]), perillas=meta[nm][\"perillas\"], media_diaria=float(x.mean()),\n                           medias_bloques=[float(b.mean()) for b in np.array_split(x, N_BLOQUES)]))\n    c = np.mean([series[k] for _, _, k in obs], axis=0) if obs else np.zeros(len(dias))\n    return dict(reglas=reglas, t_canasta=t_obs, p_seleccion=p, B=B, sesiones=len(dias), cubos=len(partes), completo=completo,\n                media_diaria_canasta=float(c.mean()), medias_bloques_canasta=[float(b.mean()) for b in np.array_split(c, N_BLOQUES)],\n                nulo_q50_q90_q95=q, serie_canasta=[float(v) for v in c], dias=[int(d) for d in dias])\n\n\ndef dias_de(fuentes):\n    d = set()\n    for _, _, f in fuentes:\n        s = f().ses; d |= set(s[(s >= VENTANA[0]) & (s <= VENTANA[1])].tolist())\n    return np.array(sorted(d))\n\n\ndef correr(fuentes, B=200, seed=20261108, log=None):\n    \"\"\"Todo en un proceso (tests y corridas chicas).\"\"\"\n    dias = dias_de(fuentes)\n    return combinar(procesar(fuentes, dias, B, seed, log), dias, B, seed)\n", "edgelab/research/regimen_offline.py": "\"\"\"B\u00fasqueda de reg\u00edmenes OFFLINE sobre cubos de operaciones (2026-11-07, pedido de Nico: \u00abinfraestructura m\u00e1s r\u00e1pida y eficiente para\nencontrar reg\u00edmenes que, aunque tengan pocos meses, tengan muchas operaciones y estabilidad entre d\u00edas, lo que les da potencia\u00bb).\n\nUn CUBO es la base de operaciones de una campa\u00f1a (etapa `CUBO` del embudo: una corrida de grilla sobre DESC + r\u00e9plica): por operaci\u00f3n,\nel nivel de cada perilla, la ejecuci\u00f3n, la sesi\u00f3n y el R neto. Con eso, cualquier regla de selecci\u00f3n de r\u00e9gimen se prueba en segundos,\nsin volver a Kaggle:\n\n  1. `series_diarias`: para cada celda evaluable (>= `min_ops` operaciones en todo el cubo), la suma diaria de R y de operaciones\n     (matrices sesi\u00f3n \u00d7 celda; las celdas son las de la grilla, con sus modos ge / eq_any / extremos).\n  2. `walk_forward`: en cada mes H, punt\u00faa con los W meses previos (s\u00f3lo sesiones cerradas antes de H) y elige UNA celda por cubo\n     (familia \u00d7 instrumento); opera las k mejores en H. Puntaje = estabilidad entre d\u00edas: t del R diario (unidad = la sesi\u00f3n, no la\n     operaci\u00f3n; las operaciones del mismo d\u00eda est\u00e1n correlacionadas) con pisos de operaciones y de d\u00edas en W.\n  3. Controles con el mismo k y la misma deduplicaci\u00f3n: AZAR (celdas elegibles sorteadas) y EST\u00c1TICA (mismo puntaje con TODO el\n     hist\u00f3rico previo a H; en H-REG-1 la calidad est\u00e1tica le gan\u00f3 a la racha: `docs/research/regimen_corto_20261106/`).\n  4. Nulo: volteo de signo por SESI\u00d3N (el mismo para todas las celdas y cubos de ese d\u00eda, conserva la correlaci\u00f3n cruzada) y se repite\n     toda la selecci\u00f3n. p = fracci\u00f3n de r\u00e9plicas con \u0394 contra azar >= el observado.\nElegir entre miles de celdas por cubo infla cualquier puntaje: el nulo repite esa misma elecci\u00f3n, as\u00ed que la correcci\u00f3n va incluida.\n\"\"\"\nfrom __future__ import annotations\n\nimport base64\nimport io\nimport zlib\nfrom dataclasses import dataclass\n\nimport numpy as np\n\nfrom edgelab.research import grilla_masiva as GM\n\n\n# ----------------------------------------------------------------------------------------------- cubo (codificaci\u00f3n)\ndef codificar(cx) -> dict:\n    \"\"\"Base de operaciones de `grilla_generica.correr(modo=\"MARG\")` \u2192 dict JSON (npz comprimido en base64).\"\"\"\n    net = np.asarray(cx[\"net\"], float); ok = np.isfinite(net)\n    I = np.stack([np.asarray(ix)[ok] for ix in cx[\"indices\"]], 1)\n    buf = io.BytesIO()\n    np.savez_compressed(buf, idx=I.astype(np.int16), ses=np.asarray(cx[\"ses\"])[ok].astype(np.int32), net=net[ok].astype(np.float32))\n    P = [(p.nombre, int(p.niveles), p.modo) for p in cx[\"perillas\"]]\n    return dict(perillas=P, n=int(ok.sum()), npz_b64=base64.b64encode(buf.getvalue()).decode())\n\n\n@dataclass\nclass Cubo:\n    nombre: str\n    perillas: list            # [GM.Perilla]\n    idx: np.ndarray           # (n_ops, n_ejes) int\n    ses: np.ndarray           # (n_ops,) yyyymmdd\n    net: np.ndarray           # (n_ops,) R neto\n\n\ndef decodificar(d: dict, nombre: str) -> Cubo:\n    z = np.load(io.BytesIO(base64.b64decode(d[\"npz_b64\"])))\n    P = [GM.Perilla(n, k, m) for n, k, m in d[\"perillas\"]]\n    return Cubo(nombre, P, z[\"idx\"].astype(np.int64), z[\"ses\"].astype(np.int64), z[\"net\"].astype(float))\n\n\n# ----------------------------------------------------------------------------------------------- series diarias por celda\n@dataclass\nclass Diario:\n    nombre: str\n    dias: np.ndarray          # (D,) sesiones ordenadas\n    celdas: np.ndarray        # (E,) \u00edndice plano de la celda en la grilla acumulada\n    S: np.ndarray             # (D, E) suma de R del d\u00eda\n    C: np.ndarray             # (D, E) operaciones del d\u00eda\n    forma: tuple\n\n\ndef series_diarias(cubo: Cubo, min_ops: int = 30) -> Diario:\n    idx = [cubo.idx[:, j] for j in range(cubo.idx.shape[1])]\n    _, _, Ctot = GM.tensor(cubo.perillas, idx, cubo.net)\n    forma = Ctot.shape; ev = np.flatnonzero(Ctot.ravel() >= min_ops)\n    dias = np.unique(cubo.ses); S = np.zeros((len(dias), len(ev)), np.float32); C = np.zeros_like(S)\n    orden = np.argsort(cubo.ses, kind=\"stable\"); ses_o = cubo.ses[orden]\n    cortes = np.searchsorted(ses_o, dias, side=\"left\").tolist() + [len(ses_o)]\n    for d in range(len(dias)):\n        o = orden[cortes[d]:cortes[d + 1]]\n        Sd, _, Cd = GM.tensor(cubo.perillas, [ix[o] for ix in idx], cubo.net[o])\n        S[d] = Sd.ravel()[ev]; C[d] = Cd.ravel()[ev]\n    return Diario(cubo.nombre, dias, ev, S, C, forma)\n\n\ndef celda_de(diario: Diario, j: int) -> list:\n    return [int(x) for x in np.unravel_index(int(diario.celdas[j]), diario.forma)]\n\n\n# ----------------------------------------------------------------------------------------------- puntaje y walk-forward\ndef puntaje(S, C, filas, min_ops=20, min_dias=10, min_pos=0.0):\n    \"\"\"t del R diario (suma del d\u00eda) en las filas dadas, s\u00f3lo d\u00edas con operaciones. NaN donde no es elegible.\"\"\"\n    s = S[filas]; c = C[filas]; act = c > 0\n    nd = act.sum(0); n_ops = c.sum(0)\n    with np.errstate(invalid=\"ignore\", divide=\"ignore\"):\n        mu = np.where(nd > 0, s.sum(0) / nd, np.nan)\n        var = np.where(nd > 1, ((s - mu) ** 2 * act).sum(0) / (nd - 1), np.nan)\n        t = mu / np.sqrt(var / nd)\n        pos = np.where(nd > 0, ((s > 0) & act).sum(0) / nd, 0.0)\n    ok = (n_ops >= min_ops) & (nd >= min_dias) & (pos >= min_pos) & np.isfinite(t)\n    return np.where(ok, t, np.nan)\n\n\ndef _mes(d): return np.asarray(d) // 100\n\n\ndef meses_positivos(S, C, dias, meses_W, min_dias_mes=4):\n    \"\"\"M\u00e1scara de celdas con R > 0 y al menos `min_dias_mes` d\u00edas con operaciones en CADA mes de W (pedido de Nico, 07/11).\"\"\"\n    ok = np.ones(S.shape[1], bool); mm = _mes(dias)\n    for m in meses_W:\n        f = mm == m; s = S[f].sum(0); nd = (C[f] > 0).sum(0)\n        ok &= (s > 0) & (nd >= min_dias_mes)\n    return ok\n\n\ndef walk_forward(diarios, W=3, k=3, min_ops=20, min_dias=10, min_pos=0.0, B_azar=200, signo=None, seed=0,\n                 cada_mes_pos=False, min_dias_mes=4) -> dict:\n    \"\"\"`diarios`: lista de Diario (uno por cubo). `signo`: dict sesi\u00f3n \u2192 \u00b11 (nulo). Devuelve por mes H: R/op elegida, azar y est\u00e1tica.\"\"\"\n    rng = np.random.default_rng(seed)\n    meses = np.unique(np.concatenate([_mes(d.dias) for d in diarios]))\n    Ss = []\n    for d in diarios:\n        if signo is None: Ss.append(d.S)\n        else: Ss.append(d.S * np.array([signo.get(int(x), 1.0) for x in d.dias], np.float32)[:, None])\n    filas_out = []\n    for h in range(W, len(meses)):\n        mH, mW = meses[h], meses[h - W:h]\n        cand, estat, elegibles = [], [], []\n        for d, S in zip(diarios, Ss):\n            mm = _mes(d.dias); fW = np.flatnonzero(np.isin(mm, mW)); fH = np.flatnonzero(mm == mH); fP = np.flatnonzero(mm < mH)\n            if not len(fW) or not len(fH): continue\n            sc = puntaje(S, d.C, fW, min_ops, min_dias, min_pos)\n            if cada_mes_pos: sc = np.where(meses_positivos(S, d.C, d.dias, mW, min_dias_mes), sc, np.nan)\n            if not np.isfinite(sc).any(): continue\n            sH, cH = S[fH].sum(0), d.C[fH].sum(0)\n            j = int(np.nanargmax(sc)); cand.append((sc[j], sH[j], cH[j]))\n            st = puntaje(S, d.C, fP, min_ops, min_dias, min_pos)\n            if np.isfinite(st).any(): js = int(np.nanargmax(st)); estat.append((st[js], sH[js], cH[js]))\n            el = np.flatnonzero(np.isfinite(sc)); elegibles.append((sH[el], cH[el]))\n        if len(cand) < k: continue\n        def _ro(lst):\n            top = sorted(lst, key=lambda x: -x[0])[:k]; c = sum(x[2] for x in top)\n            return sum(x[1] for x in top) / c if c > 0 else np.nan\n        az = []\n        for _ in range(B_azar):\n            pick = rng.choice(len(elegibles), size=k, replace=False); s = c = 0.0\n            for i in pick:\n                sH, cH = elegibles[i]; j = rng.integers(len(sH)); s += sH[j]; c += cH[j]\n            az.append(s / c if c > 0 else np.nan)\n        filas_out.append(dict(mes=int(mH), elegida=_ro(cand), azar=float(np.nanmean(az)), estatica=_ro(estat) if len(estat) >= k else np.nan,\n                              cubos=len(cand)))\n    return dict(W=W, k=k, ventanas=filas_out, **_resumen(filas_out))\n\n\ndef _resumen(filas):\n    def _t(x):\n        x = np.asarray([v for v in x if np.isfinite(v)], float)\n        return (float(x.mean()), float(x.mean() / (x.std(ddof=1) / np.sqrt(len(x)))) if len(x) > 2 and x.std() > 0 else float(\"nan\"), len(x))\n    da = _t([f[\"elegida\"] - f[\"azar\"] for f in filas]); de = _t([f[\"elegida\"] - f[\"estatica\"] for f in filas])\n    return dict(delta_azar=da[0], t_azar=da[1], delta_estatica=de[0], t_estatica=de[1], n_ventanas=da[2])\n\n\ndef nulo_signo(diarios, B=50, seed=0, **kw) -> dict:\n    \"\"\"Repite toda la selecci\u00f3n con el signo de cada sesi\u00f3n volteado (mismo signo para todos los cubos ese d\u00eda).\"\"\"\n    obs = walk_forward(diarios, seed=seed, **kw)\n    dias = np.unique(np.concatenate([d.dias for d in diarios])); rng = np.random.default_rng(seed + 1); nul = []\n    for b in range(B):\n        sg = dict(zip(dias.tolist(), rng.choice([-1.0, 1.0], size=len(dias)).tolist()))\n        nul.append(walk_forward(diarios, signo=sg, seed=seed + 2 + b, B_azar=50, **kw)[\"delta_azar\"])\n    nul = np.asarray([x for x in nul if np.isfinite(x)])\n    p = float((np.sum(nul >= obs[\"delta_azar\"]) + 1) / (len(nul) + 1)) if len(nul) else float(\"nan\")\n    return dict(observado=obs, p_nulo=p, nulo_q05_q50_q95=np.quantile(nul, [.05, .5, .95]).tolist() if len(nul) else None)\n\n\n# ----------------------------------------------------------------------------------------------- varias definiciones a la vez\nVARIANTES = {   # 2026-11-07 (Nico: \u00abm\u00e1s d\u00edas o m\u00e1s estabilidad entre d\u00edas podr\u00edan reemplazar a los 3 meses\u00bb); se corrigen juntas\n    \"A_3M_CADA_MES\": dict(W=3, min_ops=30, min_dias=20, min_pos=0.50, cada_mes_pos=True, min_dias_mes=4),\n    \"B_2M_ESTABLE\": dict(W=2, min_ops=30, min_dias=20, min_pos=0.55, cada_mes_pos=True, min_dias_mes=6),\n    \"C_1M_MUY_ESTABLE\": dict(W=1, min_ops=25, min_dias=12, min_pos=0.60),\n    \"D_3M_SIN_CADA_MES\": dict(W=3, min_ops=30, min_dias=20, min_pos=0.50),\n}\n\n\ndef nulo_signo_multi(diarios, variantes=None, k=3, B=50, seed=0) -> dict:\n    \"\"\"Todas las variantes contra el MISMO nulo de signo por sesi\u00f3n, corregido por haberlas probado juntas: en cada r\u00e9plica se toma el\n    m\u00e1ximo \u0394 contra azar entre las variantes, y el p de cada variante es la fracci\u00f3n de r\u00e9plicas cuyo m\u00e1ximo lo iguala o supera.\"\"\"\n    variantes = variantes or VARIANTES\n    obs = {n: walk_forward(diarios, k=k, seed=seed, **v) for n, v in variantes.items()}\n    dias = np.unique(np.concatenate([d.dias for d in diarios])); rng = np.random.default_rng(seed + 1); maxi = []\n    for b in range(B):\n        sg = dict(zip(dias.tolist(), rng.choice([-1.0, 1.0], size=len(dias)).tolist()))\n        vals = [walk_forward(diarios, k=k, signo=sg, seed=seed + 2 + b, B_azar=50, **v)[\"delta_azar\"] for v in variantes.values()]\n        vals = [x for x in vals if np.isfinite(x)]\n        if vals: maxi.append(max(vals))\n    maxi = np.asarray(maxi)\n    out = {}\n    for n, o in obs.items():\n        p = float((np.sum(maxi >= o[\"delta_azar\"]) + 1) / (len(maxi) + 1)) if len(maxi) and np.isfinite(o[\"delta_azar\"]) else float(\"nan\")\n        out[n] = dict(observado={kk: vv for kk, vv in o.items() if kk != \"ventanas\"}, ventanas=o[\"ventanas\"], p_familia=p)\n    return dict(variantes=out, nulo_max_q50_q95=np.quantile(maxi, [.5, .95]).tolist() if len(maxi) else None, B=len(maxi))\n\n\n# ----------------------------------------------------------------------------------------------- versi\u00f3n en flujo (memoria acotada)\ndef _cubo_mensual(cubo: Cubo, min_ops: int, G: np.ndarray, dias_glob: np.ndarray):\n    \"\"\"Recorre el cubo mes a mes sin armar la matriz diaria completa. Para cada mes con operaciones devuelve (mes, suma con signo\n    (B+1, E), suma de cuadrados (E,), d\u00edas activos (E,), d\u00edas positivos con signo (B+1, E), operaciones (E,)). G: signos (B+1, d\u00edas\n    globales); la fila 0 es el observado (todo +1).\"\"\"\n    idx = [cubo.idx[:, j] for j in range(cubo.idx.shape[1])]\n    _, _, Ctot = GM.tensor(cubo.perillas, idx, cubo.net); ev = np.flatnonzero(Ctot.ravel() >= min_ops)\n    orden = np.argsort(cubo.ses, kind=\"stable\"); ses_o = cubo.ses[orden]; dias = np.unique(ses_o)\n    cortes = np.searchsorted(ses_o, dias, side=\"left\").tolist() + [len(ses_o)]\n    gcol = np.searchsorted(dias_glob, dias); meses = _mes(dias)\n    for m in np.unique(meses):\n        fd = np.flatnonzero(meses == m); S = np.zeros((len(fd), len(ev)), np.float32); C = np.zeros_like(S)   # float32 como el original\n        for r, d in enumerate(fd):\n            o = orden[cortes[d]:cortes[d + 1]]\n            Sd, _, Cd = GM.tensor(cubo.perillas, [ix[o] for ix in idx], cubo.net[o]); S[r] = Sd.ravel()[ev]; C[r] = Cd.ravel()[ev]\n        g = G[:, gcol[fd]].astype(np.float32); act = C > 0\n        npos = (g > 0).astype(np.float32) @ ((S > 0) & act).astype(np.float32) + (g < 0).astype(np.float32) @ ((S < 0) & act).astype(np.float32)\n        yield int(m), g @ S, (S.astype(np.float64) ** 2).sum(0), act.sum(0).astype(np.float64), npos, C.sum(0).astype(np.float64)\n\n\ndef _puntaje_agr(s, sq, nd, npos, ops, min_ops, min_dias, min_pos):\n    \"\"\"`puntaje` a partir de sumas: s, npos (B+1, E); sq, nd, ops (E,). Mismo t del R diario sobre d\u00edas activos.\"\"\"\n    with np.errstate(invalid=\"ignore\", divide=\"ignore\"):\n        mu = np.where(nd > 0, s / nd, np.nan)\n        var = np.where(nd > 1, (sq - nd * mu ** 2) / (nd - 1), np.nan)\n        t = mu / np.sqrt(var / nd)\n        pos = np.where(nd > 0, npos / np.maximum(nd, 1), 0.0)\n    ok = (ops >= min_ops) & (nd >= min_dias) & (pos >= min_pos) & np.isfinite(t)\n    return np.where(ok, t, np.nan)\n\n\ndef buscar_streaming(fuentes, variantes=None, k=3, B=50, seed=0, min_ops_serie=30, B_azar_obs=200, B_azar_nulo=50, max_eleg=256,\n                     detalle=False, punto_control=None, log=None):\n    \"\"\"`nulo_signo_multi` en flujo: un cubo por vez y un mes por vez, con el observado y las B r\u00e9plicas del nulo juntos. `fuentes`:\n    lista de (nombre, funci\u00f3n que devuelve el Cubo). Elegida y est\u00e1tica son id\u00e9nticas a `walk_forward` (mismo puntaje y mismos\n    signos: la misma semilla que `nulo_signo_multi`); el azar sortea dentro de una muestra uniforme de hasta `max_eleg` celdas\n    elegibles por cubo (sigue siendo uniforme). Memoria: la de un mes de un cubo.\"\"\"\n    variantes = variantes or VARIANTES; nv = list(variantes)\n    sesiones = []\n    for nombre, f in fuentes:\n        pd_ = (punto_control / f\"{nombre}_sesiones.npy\") if punto_control else None\n        if pd_ is not None and pd_.exists(): sesiones.append(np.load(pd_)); continue\n        x = np.unique(f().ses); sesiones.append(x)\n        if pd_ is not None: punto_control.mkdir(parents=True, exist_ok=True); np.save(pd_, x)\n    dias_glob = np.unique(np.concatenate(sesiones)); meses_glob = np.unique(_mes(dias_glob))\n    rng = np.random.default_rng(seed + 1)\n    G = np.ones((B + 1, len(dias_glob)))\n    for b in range(B): G[b + 1] = rng.choice([-1.0, 1.0], size=len(dias_glob))\n    reg = {(v, h): dict(cand=[], estat=[], eleg=[]) for v in nv for h in range(len(meses_glob))}   # por cubo, arrays (B+1,)\n    import hashlib, pickle, time as _t, zlib as _z\n    huella = hashlib.sha256(repr((sorted(variantes.items()), k, B, seed, min_ops_serie, max_eleg, len(dias_glob))).encode()).hexdigest()[:12]\n    for nc, (nombre, f) in enumerate(fuentes):\n        pc = (punto_control / f\"{nombre}_{huella}.pkl\") if punto_control else None\n        if pc is not None and pc.exists():                       # 2026-11-08: un reinicio del contenedor no pierde los cubos hechos\n            for key, R in pickle.loads(pc.read_bytes()).items():\n                for c in (\"cand\", \"estat\", \"eleg\"): reg[key][c] += R[c]\n            continue\n        t0 = _t.time(); rs = np.random.default_rng([seed + 7, _z.crc32(nombre.encode())])   # independiente del orden de los cubos\n        propio = {key: dict(cand=[], estat=[], eleg=[]) for key in reg}\n        cubo = f(); ventana = []; acum = None\n        for m, s, sq, nd, npos, ops in _cubo_mensual(cubo, min_ops_serie, G, dias_glob):\n            h = int(np.searchsorted(meses_glob, m))\n            for v in nv:\n                p = variantes[v]; W = p[\"W\"]\n                win = [x for x in ventana if x[0] in set(meses_glob[max(0, h - W):h].tolist())]\n                if not win or h < W: continue\n                ws = sum(x[1] for x in win); wsq = sum(x[2] for x in win); wnd = sum(x[3] for x in win)\n                wnp = sum(x[4] for x in win); wop = sum(x[5] for x in win)\n                sc = _puntaje_agr(ws, wsq, wnd, wnp, wop, p[\"min_ops\"], p[\"min_dias\"], p.get(\"min_pos\", 0.0))\n                if p.get(\"cada_mes_pos\"):\n                    okm = np.ones_like(sc, bool)\n                    for mw in meses_glob[h - W:h]:\n                        x = next((y for y in win if y[0] == mw), None)\n                        okm &= (x[1] > 0) & (x[3] >= p.get(\"min_dias_mes\", 4)) if x is not None else False\n                    sc = np.where(okm, sc, np.nan)\n                st = (_puntaje_agr(acum[0], acum[1], acum[2], acum[3], acum[4], p[\"min_ops\"], p[\"min_dias\"], p.get(\"min_pos\", 0.0))\n                      if acum is not None else np.full_like(sc, np.nan))\n                R = propio[(v, h)]\n                for b in range(B + 1):\n                    fila = sc[b]\n                    if not np.isfinite(fila).any(): R[\"cand\"].append(None); R[\"estat\"].append(None); R[\"eleg\"].append(None); continue\n                    j = int(np.nanargmax(fila)); cand = (fila[j], s[b, j], ops[j])\n                    fs = st[b]; est = None\n                    if np.isfinite(fs).any(): js = int(np.nanargmax(fs)); est = (fs[js], s[b, js], ops[js])\n                    el = np.flatnonzero(np.isfinite(fila))\n                    if len(el) > max_eleg: el = rs.choice(el, size=max_eleg, replace=False)\n                    R[\"cand\"].append((b, cand)); R[\"estat\"].append((b, est)); R[\"eleg\"].append((b, s[b, el], ops[el]))\n            ventana = (ventana + [(m, s, sq, nd, npos, ops)])[-3:]\n            acum = (s, sq, nd, npos, ops) if acum is None else tuple(a + x for a, x in zip(acum, (s, sq, nd, npos, ops)))\n        del cubo\n        for key, R in propio.items():\n            for c in (\"cand\", \"estat\", \"eleg\"): reg[key][c] += R[c]\n        if pc is not None: pc.write_bytes(pickle.dumps(propio))\n        if log: log(f\"cubo {nc + 1}/{len(fuentes)} {nombre} {_t.time() - t0:.0f}s\")\n    obs, maxi = {}, []\n    filas_b = {v: {b: [] for b in range(B + 1)} for v in nv}\n    for (v, h), R in sorted(reg.items(), key=lambda x: x[0][1]):\n        for b in range(B + 1):\n            cand = [c[1] for c in R[\"cand\"] if c is not None and c[0] == b]\n            if len(cand) < k: continue\n            est = [e[1] for e in R[\"estat\"] if e is not None and e[0] == b and e[1] is not None]\n            eleg = [(e[1], e[2]) for e in R[\"eleg\"] if e is not None and e[0] == b]\n            def _ro(lst):\n                top = sorted(lst, key=lambda x: -x[0])[:k]; c = sum(x[2] for x in top)\n                return sum(x[1] for x in top) / c if c > 0 else np.nan\n            ra = np.random.default_rng(seed + 2 + b + 1000 * h); az = []\n            for _ in range(B_azar_obs if b == 0 else B_azar_nulo):\n                pick = ra.choice(len(eleg), size=k, replace=False); ss = cc = 0.0\n                for i in pick:\n                    sH, cH = eleg[i]; j = ra.integers(len(sH)); ss += sH[j]; cc += cH[j]\n                az.append(ss / cc if cc > 0 else np.nan)\n            filas_b[v][b].append(dict(mes=int(meses_glob[h]), elegida=_ro(cand), azar=float(np.nanmean(az)),\n                                      estatica=_ro(est) if len(est) >= k else np.nan, cubos=len(cand)))\n    for b in range(1, B + 1):\n        vals = [_resumen(filas_b[v][b])[\"delta_azar\"] for v in nv]; vals = [x for x in vals if np.isfinite(x)]\n        if vals: maxi.append(max(vals))\n    maxi = np.asarray(maxi); out = {}\n    for v in nv:\n        o = _resumen(filas_b[v][0])\n        p = float((np.sum(maxi >= o[\"delta_azar\"]) + 1) / (len(maxi) + 1)) if len(maxi) and np.isfinite(o[\"delta_azar\"]) else float(\"nan\")\n        out[v] = dict(observado=dict(W=variantes[v][\"W\"], k=k, **o), ventanas=filas_b[v][0], p_familia=p)\n    res = dict(variantes=out, nulo_max_q50_q95=np.quantile(maxi, [.5, .95]).tolist() if len(maxi) else None, B=len(maxi),\n               cubos=len(fuentes), dias=len(dias_glob))\n    if detalle: res[\"filas\"] = filas_b; res[\"signos\"] = {b: dict(zip(dias_glob.tolist(), G[b].tolist())) for b in range(B + 1)}\n    return res\n", "edgelab/research/grilla_masiva.py": "\"\"\"N\u00facleo gen\u00e9rico para experimentos de GRILLA MASIVA (millones de variantes) con el embudo de EdgeLab. Reutilizable.\n\nIdea: cada operaci\u00f3n simulada se calcula UNA vez. Cada perilla que s\u00f3lo FILTRA operaciones se discretiza en niveles ordinales;\nlas perillas que cambian la ejecuci\u00f3n (entrada, salida, objetivo...) son dimensiones de agrupamiento. Con sumas acumuladas\nsobre un tensor salen las estad\u00edsticas de TODAS las celdas sin recorrer las operaciones por cada combinaci\u00f3n:\ncosto ~ O(operaciones + celdas), no O(operaciones \u00d7 celdas).\n\nModos de perilla (c\u00f3mo se acumula su dimensi\u00f3n):\n  \"grupo\"     dimensi\u00f3n de agrupamiento: cada nivel es una celda distinta (sin acumular)\n  \"ge\"        umbral m\u00ednimo: la celda de nivel i toma niveles >= i  (p. ej. alejamiento >= 1, 2, 4, 8)\n  \"le\"        umbral m\u00e1ximo: niveles <= i                          (p. ej. comercio <= 0, 1, 3, cualquiera)\n  \"eq_any\"    cada nivel por separado + un nivel extra \"cualquiera\"\n  \"extremos\"  primer nivel, \u00faltimo nivel y \"cualquiera\"             (p. ej. tercio bajo / alto / cualquiera)\nUso:\n    P = [Perilla(\"N\", 3, \"grupo\"), Perilla(\"A/H\", 4, \"ge\"), Perilla(\"comercio\", 4, \"le\"), Perilla(\"p_vol\", 3, \"eq_any\")]\n    S, Q, C = tensor(P, [ni, ai, ci, pi], net)       # \u00edndices de nivel por operaci\u00f3n (-1 = fuera)\n    st = estadisticas(S, Q, C); nom = criba(st, q=0.10)\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom statistics import NormalDist\n\nimport math\nimport os\n\nimport numpy as np\n\ntry:\n    from numba import njit, prange\nexcept ImportError:                                    # sin numba: misma l\u00f3gica en Python (lenta, s\u00f3lo para tests m\u00ednimos)\n    def njit(*a, **k):\n        return (lambda f: f) if not (a and callable(a[0])) else a[0]\n    prange = range\n\n_N = NormalDist()\n_MODOS = {\"grupo\": 0, \"ge\": 1, \"le\": 2, \"eq_any\": 3, \"extremos\": 4}\n# Memoria m\u00e1xima para guardar la matriz bootstrap estandarizada (B x celdas evaluables, float32) entre los pasos del step-down.\n# Si no entra, se recalcula por bloques en cada paso (mismo resultado, m\u00e1s tiempo, memoria acotada).\nRW_MEMORIA_BYTES = int(float(os.environ.get(\"EDGELAB_RW_MEMORIA_GB\", \"2\")) * 2**30)\nRW_BLOQUE_BYTES = int(float(os.environ.get(\"EDGELAB_RW_BLOQUE_MB\", \"1024\")) * 2**20)\n\n\n@dataclass(frozen=True)\nclass Perilla:\n    nombre: str\n    niveles: int\n    modo: str = \"grupo\"\n\n    def tamano_celdas(self) -> int:\n        return {\"grupo\": self.niveles, \"ge\": self.niveles, \"le\": self.niveles, \"eq_any\": self.niveles + 1, \"extremos\": 3}[self.modo]\n\n\ndef tensor(perillas, indices, valores, pesos=None):\n    \"\"\"Suma, suma de cuadrados y conteo por celda (forma = tamano_celdas de cada perilla). \u00cdndices < 0 o NaN quedan fuera.\n    `pesos` (opcional, por operaci\u00f3n) pondera las tres sumas: lo usa el remuestreo por sesiones de `romano_wolf`.\"\"\"\n    v = np.asarray(valores, float); ok = np.isfinite(v)\n    for p, ix in zip(perillas, indices):\n        ok &= (np.asarray(ix) >= 0) & (np.asarray(ix) < p.niveles)\n    shp = tuple(p.niveles for p in perillas)\n    flat = np.ravel_multi_index(tuple(np.asarray(ix)[ok] for ix in indices), shp)\n    out = []; pw = None if pesos is None else np.asarray(pesos, float)[ok]\n    for w in (v[ok], v[ok] ** 2, None):\n        if pw is not None: w = pw if w is None else w * pw\n        X = np.bincount(flat, weights=w, minlength=int(np.prod(shp))).astype(float).reshape(shp)\n        for ax, p in enumerate(perillas):\n            X = acumular(X, ax, p.modo)\n        out.append(X)\n    return out\n\n\ndef acumular(X, ax, modo):\n    if modo == \"grupo\": return X\n    if modo == \"ge\": return np.flip(np.cumsum(np.flip(X, ax), ax), ax)\n    if modo == \"le\": return np.cumsum(X, ax)\n    if modo == \"eq_any\": return np.concatenate([X, X.sum(ax, keepdims=True)], ax)\n    if modo == \"extremos\":\n        n = X.shape[ax]\n        return np.concatenate([np.take(X, [0], ax), np.take(X, [n - 1], ax), X.sum(ax, keepdims=True)], ax)\n    raise ValueError(modo)\n\n\ndef mascara(perillas, indices, celda):\n    \"\"\"Qu\u00e9 operaciones pertenecen a una celda (para la inferencia cara sobre sobrevivientes).\"\"\"\n    m = np.ones(len(indices[0]), bool)\n    for p, ix, c in zip(perillas, indices, celda):\n        ix = np.asarray(ix)\n        if p.modo == \"grupo\": m &= ix == c\n        elif p.modo == \"ge\": m &= ix >= c\n        elif p.modo == \"le\": m &= ix <= c\n        elif p.modo == \"eq_any\": m &= (ix == c) if c < p.niveles else (ix >= 0)\n        elif p.modo == \"extremos\": m &= (ix == (0 if c == 0 else p.niveles - 1)) if c < 2 else (ix >= 0)\n    return m\n\n\ndef estadisticas(S, Q, C, min_n=30):\n    \"\"\"Media, t (varianza por operaci\u00f3n) y p unilateral (media > 0). Celdas con < min_n operaciones: p = 1 (se cuentan igual).\"\"\"\n    with np.errstate(invalid=\"ignore\", divide=\"ignore\"):\n        mu = S / C; var = (Q - C * mu ** 2) / (C - 1); t = mu / np.sqrt(var / C)\n    ev = (C >= min_n) & np.isfinite(t)\n    p = np.ones(C.shape)\n    # 2026-11-03 (decisi\u00f3n de Nico, opci\u00f3n 1 de PROPUESTA_COLA_T_TAMIZ_FDR_20261103.md): p con la cola t de Student con n \u2212 1 g.l.\n    # La cola normal nominaba ruido en celdas de 30-40 operaciones con m de millones (umbral BH ~6e-8, donde normal y t difieren\n    # 100-1000 veces). Con n grande es la misma cola.\n    if ev.any(): p[ev] = _cola_t_superior(t[ev], C[ev] - 1.0)               # sin evaluables: todo p = 1 (no revienta)\n    return dict(media=mu, t=t, p=p, n=C, evaluable=ev)\n\n\ndef criba(st, q=0.10, metodo=\"storey\", tope=1000, m_sobre=\"evaluables\"):\n    \"\"\"Tamiz FDR. Devuelve las nominadas, ordenadas por t, y los q-valores de TODAS las celdas (las no evaluables con q = 1).\n    m = celdas EVALUABLES (2026-10-24, falsos negativos; filtrado independiente, Bourgon, Gentleman y Huber 2010): el filtro\n    \u00abn >= min_n\u00bb depende s\u00f3lo del conteo de operaciones, no del signo ni del tama\u00f1o del P&L, as\u00ed que bajo la nula no cambia la\n    distribuci\u00f3n de los p que pasan y puede salir del tamiz. Antes las no evaluables entraban con p = 1: inflaban m (y \u03c00 de\n    Storey) sin poder rechazar nunca; en AREAS-EXP-1 v1.4 eran 2/3 de las celdas (995.328 contra 315.654 evaluables).\n    `m_sobre=\"celdas\"` reproduce la regla anterior. Se publican las dos cuentas (`m`, `evaluables`, `celdas`).\"\"\"\n    from edgelab.funnel.escalera import tamiz_fdr\n    ev = st[\"evaluable\"].ravel(); pf = st[\"p\"].ravel()\n    if m_sobre == \"celdas\": idx = np.arange(pf.size)\n    elif m_sobre == \"evaluables\": idx = np.flatnonzero(ev)\n    else: raise ValueError(\"m_sobre: evaluables | celdas\")\n    qv = np.ones(pf.size)\n    if len(idx):\n        tz = tamiz_fdr(pf[idx], q, metodo); qv[idx] = np.asarray(tz[\"q_valores\"]); pi0 = tz[\"pi0\"]\n    else: pi0 = 1.0\n    nom = np.flatnonzero(qv <= q); n_nom = len(nom)\n    nom = nom[np.argsort(-st[\"t\"].ravel()[nom])][:tope] if n_nom else nom\n    return dict(nominadas=[tuple(int(v) for v in np.unravel_index(f, st[\"n\"].shape)) for f in nom], pi0=pi0, q=q, m=int(len(idx)), m_sobre=m_sobre,\n                evaluables=int(ev.sum()), celdas=int(st[\"n\"].size), n_nominadas=int(n_nom), recortadas_por_tope=max(0, n_nom - tope),\n                q_valores=qv.reshape(st[\"n\"].shape))   # completo (sin tope): para marcar la nominaci\u00f3n de cada pista\n\n\ndef vecinos(celda, perillas, ejes_ordinales):\n    \"\"\"Celdas a \u00b11 nivel en cada perilla ordinal (para la meseta).\"\"\"\n    out = []\n    for ax in ejes_ordinales:\n        lim = perillas[ax].tamano_celdas() - (1 if perillas[ax].modo in (\"eq_any\", \"extremos\") else 0)\n        for d in (-1, 1):\n            v = list(celda); v[ax] += d\n            if 0 <= v[ax] < lim: out.append(tuple(v))\n    return out\n\n\ndef meseta(st, celda, perillas, ejes_ordinales, min_n=30):\n    \"\"\"Regla fija del embudo: >= 2/3 de los vecinos positivos y mediana de vecinos >= 50 % de la celda.\"\"\"\n    v = [st[\"media\"][x] for x in vecinos(celda, perillas, ejes_ordinales) if st[\"n\"][x] >= min_n]\n    ok = bool(v and np.mean(np.array(v) > 0) >= 2 / 3 and np.median(v) >= 0.5 * st[\"media\"][celda])\n    return dict(meseta=ok, vecinos=len(v), fraccion_positivos=float(np.mean(np.array(v) > 0)) if v else None)\n\n\ndef resumen_nulo(st, perillas, q=0.10, referencia=None, potencia=0.8):\n    \"\"\"Lo que publica toda grilla, nomine o no (regla \u00abtodo nulo publica su MDE\u00bb). Por celda evaluable, con el error est\u00e1ndar\n    por operaci\u00f3n: MDE del tamiz (nivel q/m, lo que har\u00eda falta para ser nominada entre m celdas) y MDE de confirmaci\u00f3n (5 %).\n    Agregado por nivel de cada perilla (m\u00ednimo y mediana), cu\u00e1ntas celdas detectar\u00edan `referencia` (p. ej. 1x la fricci\u00f3n),\n    y la distribuci\u00f3n de t en los dos canales (cola positiva y negativa: un efecto bidireccional no se pierde en el promedio).\"\"\"\n    from edgelab.funnel.escalera import ALFA_CONFIRMACION\n    ev = st[\"evaluable\"]; m = max(int(ev.sum()), 1)                  # m del tamiz = evaluables (filtrado independiente, ver `criba`)\n    with np.errstate(invalid=\"ignore\", divide=\"ignore\"):\n        se = np.abs(st[\"media\"] / st[\"t\"])\n    zp = _N.inv_cdf(potencia); z_tamiz = _N.inv_cdf(1 - q / m); z_conf = _N.inv_cdf(1 - ALFA_CONFIRMACION)\n    mde_t, mde_c = (z_tamiz + zp) * se, (z_conf + zp) * se\n    out = dict(celdas=int(st[\"n\"].size), evaluables=int(ev.sum()), m_tamiz=m, z_tamiz=round(z_tamiz, 3), z_confirmacion=round(z_conf, 3), potencia=potencia)\n    if not ev.any(): return out\n    tv = st[\"t\"][ev]\n    out[\"t\"] = dict(max=float(tv.max()), min=float(tv.min()), **{f\"q{int(k * 1000):03d}\": float(np.quantile(tv, k)) for k in (0.001, 0.01, 0.5, 0.99, 0.999)},\n                    sobre_z_tamiz=int((tv > z_tamiz).sum()), bajo_menos_z_tamiz=int((tv < -z_tamiz).sum()))\n    out[\"mde_tamiz\"] = dict(min=float(np.nanmin(mde_t[ev])), mediana=float(np.nanmedian(mde_t[ev])))\n    out[\"mde_confirmacion\"] = dict(min=float(np.nanmin(mde_c[ev])), mediana=float(np.nanmedian(mde_c[ev])))\n    if referencia is not None:\n        out[\"referencia\"] = float(referencia)\n        out[\"detectarian_referencia\"] = dict(tamiz=int((mde_t[ev] <= referencia).sum()), confirmacion=int((mde_c[ev] <= referencia).sum()))\n    por = {}\n    for ax, p in enumerate(perillas):\n        filas = []\n        for v in range(st[\"n\"].shape[ax]):\n            sl = [slice(None)] * st[\"n\"].ndim; sl[ax] = v; e = ev[tuple(sl)]\n            if not e.any(): filas.append(dict(nivel=v, evaluables=0)); continue\n            mt = mde_t[tuple(sl)][e]\n            filas.append(dict(nivel=v, evaluables=int(e.sum()), mde_tamiz_min=float(np.nanmin(mt)), mde_tamiz_mediana=float(np.nanmedian(mt)),\n                              t_max=float(st[\"t\"][tuple(sl)][e].max()), t_min=float(st[\"t\"][tuple(sl)][e].min())))\n        por[p.nombre] = filas\n    out[\"por_perilla\"] = por\n    return out\n\n\ndef romano_wolf(perillas, indices, valores, sesiones, st, B=1000, alfa=0.10, seed=0, pasos=5):\n    \"\"\"Umbral de m\u00e1ximo t MEDIDO en los datos (Romano y Wolf 2005, step-down), con remuestreo de SESIONES enteras.\n    Respeta la correlaci\u00f3n real entre celdas anidadas (que el tamiz FDR trata como independientes) y la dependencia dentro de\n    la sesi\u00f3n (que la t por operaci\u00f3n ignora). S\u00f3lo celdas evaluables cuentan. t_j = media_j / sd_bootstrap_j; nula:\n    max_j (media*_j - media_j) / sd_j. Controla la tasa de al menos un falso positivo (FWER) en `alfa`.\"\"\"\n    ev = st[\"evaluable\"].ravel(); n_ev = int(ev.sum()); m0 = st[\"media\"].ravel()[ev].astype(np.float32)\n    out = dict(B=B, alfa=alfa, evaluables=n_ev, seed=seed)\n    if not n_ev: return dict(out, t=np.full(st[\"n\"].shape, np.nan), umbral=np.inf, umbrales=[], rechazadas=[], t_max=float(\"nan\"),\n                             p_rw_del_maximo=float(\"nan\"), nula_max_q={})\n    us, inv = np.unique(np.asarray(sesiones), return_inverse=True); rng = np.random.default_rng(seed)\n    W = np.stack([rng.multinomial(len(us), np.full(len(us), 1 / len(us))) for _ in range(B)]).astype(np.float64)   # mismo orden de sorteo\n    bs = _Bootstrap(perillas, indices, valores, inv, len(us), ev, W)\n    sd = np.empty(n_ev, np.float32)\n    for a, b, Mb in bs.bloques(): sd[a:b] = np.nanstd(Mb, 0)\n    sd[~(sd > 0)] = np.nan; t = m0 / sd\n    bs.estandarizar(m0, sd)                                        # desde ac\u00e1 cada bloque es la desviaci\u00f3n estandarizada\n    activos = np.isfinite(t); rech = np.zeros(n_ev, bool); umbrales = []\n    for _ in range(pasos):\n        mx = bs.maximo(activos); c = float(np.quantile(mx, 1 - alfa)); umbrales.append(c)\n        nuevo = activos & (t > c)\n        if not nuevo.any(): break\n        rech |= nuevo; activos &= ~nuevo\n    mx0 = bs.maximo(np.isfinite(t))\n    T = np.full(st[\"n\"].size, np.nan); T[np.flatnonzero(ev)] = t; T = T.reshape(st[\"n\"].shape)\n    cel = [tuple(int(v) for v in np.unravel_index(f, st[\"n\"].shape)) for f in np.flatnonzero(ev)[rech]]\n    tmax = float(np.nanmax(t))\n    return dict(out, t=T, umbral=umbrales[0], umbrales=umbrales, rechazadas=cel, t_max=tmax,\n                p_rw_del_maximo=float((1 + np.sum(mx0 >= tmax)) / (B + 1)),   # (k+1)/(B+1): nunca 0 (decisi\u00f3n 2026-10-24)\n                nula_max_q=dict(q50=float(np.quantile(mx0, .5)), q90=float(np.quantile(mx0, .9)), q95=float(np.quantile(mx0, .95))))\n\n\n\ndef criba_maxt(perillas, indices, valores, sesiones, st, B=1000, alfa=0.10, seed=20261030):\n    \"\"\"Criba con error familiar bajo dependencia: Westfall-Young maxT por inversi\u00f3n de signo de SESIONES enteras.\n    T_j = suma_s x_sj / ra\u00edz(suma_s x_sj\u00b2), con x_sj el P&L de la celda j en la sesi\u00f3n s: el denominador no depende de los signos,\n    as\u00ed que la nula es exacta si cada sesi\u00f3n es sim\u00e9trica en signo, sin aproximaci\u00f3n normal y sin importar la correlaci\u00f3n entre\n    celdas (el mismo signo se aplica a todas las celdas de la sesi\u00f3n) ni dentro de la sesi\u00f3n.\n    Distinto de `romano_wolf`, que usa media / sd bootstrap sin reestudentizar cada r\u00e9plica: medido en el control nulo de CVGAP-NQ\n    rechaz\u00f3 en 3 de 3 semillas (18, 12 y 465 celdas), sobre todo celdas de ~30 sesiones.\n    Nominadas: T_j estrictamente sobre el umbral, lo que implica p_ajustado = (1 + #{max* >= T_j}) / (B + 1) <= alfa.\"\"\"\n    ev = st[\"evaluable\"].ravel(); n_ev = int(ev.sum()); shp = st[\"n\"].shape\n    out = dict(metodo=\"maxt_signos_sesion\", B=B, alfa=alfa, seed=seed, evaluables=n_ev)\n    if not n_ev: return dict(out, t=np.full(shp, np.nan), p_ajustado=np.ones(shp), umbral=np.inf, t_max=float(\"nan\"), p_del_maximo=float(\"nan\"),\n                             nula_max_q={}, nominadas=[], n_nominadas=0)\n    us, inv = np.unique(np.asarray(sesiones), return_inverse=True)\n    W = np.random.default_rng(seed).choice((-1.0, 1.0), size=(B, len(us)))\n    bs = _Bootstrap(perillas, indices, valores, inv, len(us), ev, W)\n    T = np.full(n_ev, np.nan); mx = np.full(B, -np.inf)\n    for a in range(0, n_ev, bs.ancho):\n        b = min(n_ev, a + bs.ancho); ES = bs._sumas(a, b)[0]; d = np.sqrt((ES ** 2).sum(0))\n        with np.errstate(invalid=\"ignore\", divide=\"ignore\"):\n            T[a:b] = ES.sum(0) / d; R = (W @ ES) / d\n        mx = np.maximum(mx, np.where(np.isfinite(R), R, -np.inf).max(1))\n    orden = np.sort(mx); k = int(math.floor(alfa * (B + 1)))                   # el k-\u00e9simo m\u00e1ximo: nadie sobre \u00e9l tiene p_ajustado > alfa\n    umbral = float(orden[B - k]) if k >= 1 else np.inf\n    ok = np.isfinite(T); p_aj = np.ones(n_ev)\n    p_aj[ok] = (1 + B - np.searchsorted(orden, T[ok], side=\"left\")) / (B + 1)\n    nom = np.flatnonzero(ok & (T > umbral)); nom = nom[np.argsort(-T[nom], kind=\"stable\")]\n    TT = np.full(st[\"n\"].size, np.nan); PP = np.ones(st[\"n\"].size); TT[np.flatnonzero(ev)] = T; PP[np.flatnonzero(ev)] = p_aj\n    return dict(out, t=TT.reshape(shp), p_ajustado=PP.reshape(shp), umbral=umbral, t_max=float(np.nanmax(T)) if ok.any() else float(\"nan\"),\n                p_del_maximo=float(p_aj.min()), nula_max_q=dict(q50=float(np.quantile(mx, .5)), q90=float(np.quantile(mx, .9)), q95=float(np.quantile(mx, .95))),\n                nominadas=[tuple(int(v) for v in np.unravel_index(f, shp)) for f in np.flatnonzero(ev)[nom]], n_nominadas=int(len(nom)))\n\n\n# ------------------------------------------------------------------ bootstrap por sesiones sin recorrer el tensor denso B veces\n# Antes: B llamadas a `tensor` (bincount + acumulaci\u00f3n de TODAS las celdas, vac\u00edas incluidas) => O(B x celdas x perillas).\n# Ahora: (1) se agregan las operaciones por (sesi\u00f3n, celda cruda); (2) cada par se expande una sola vez a las celdas EVALUABLES\n# que lo contienen (misma regla que `mascara`), dando E_S y E_C de forma sesiones x evaluables; (3) cada r\u00e9plica bootstrap es\n# un producto matricial: medias* = (W @ E_S) / (W @ E_C). Mismo sorteo, mismas celdas, mismo resultado (or\u00e1culo:\n# `_medias_bootstrap_denso`, test `test_romano_wolf_igual_al_denso`). Por bloques de columnas: memoria acotada.\n\n@njit(cache=False, parallel=True)\ndef _expandir(ses_ini, lv, sv, cv, fmin, fmax, niveles, modos, strides, evmap, lo, hi, flo, fhi, ES, EC):\n    \"\"\"Pares ordenados por sesi\u00f3n (`ses_ini`: inicio de cada sesi\u00f3n): en paralelo por sesi\u00f3n, cada hilo escribe s\u00f3lo su fila.\n    Un par cuyo rango de celdas [fmin, fmax] no toca el bloque [flo, fhi] se salta sin expandir.\"\"\"\n    A = lv.shape[1]\n    mx = 2\n    for a in range(A): mx = max(mx, niveles[a] + 1)\n    for s in prange(len(ses_ini) - 1):\n        buf = np.empty((A, mx), np.int64); lens = np.empty(A, np.int64); pos = np.zeros(A, np.int64)\n        _expandir_sesion(s, ses_ini[s], ses_ini[s + 1], lv, sv, cv, fmin, fmax, niveles, modos, strides, evmap, lo, hi, flo, fhi,\n                         ES, EC, buf, lens, pos)\n\n\n@njit(cache=False)\ndef _expandir_sesion(s, p0, p1, lv, sv, cv, fmin, fmax, niveles, modos, strides, evmap, lo, hi, flo, fhi, ES, EC, buf, lens, pos):\n    A = lv.shape[1]\n    for p in range(p0, p1):\n        if fmax[p] < flo or fmin[p] > fhi: continue\n        for a in range(A):\n            l = lv[p, a]; n = niveles[a]; m = modos[a]; k = 0\n            if m == 0:\n                buf[a, 0] = l; k = 1\n            elif m == 1:                                            # ge: la celda c toma niveles >= c  ->  c <= l\n                for c in range(l + 1): buf[a, k] = c; k += 1\n            elif m == 2:                                            # le: niveles <= c  ->  c >= l\n                for c in range(l, n): buf[a, k] = c; k += 1\n            elif m == 3:                                            # eq_any: su nivel y \u00abcualquiera\u00bb\n                buf[a, 0] = l; buf[a, 1] = n; k = 2\n            else:                                                   # extremos: 0 = primero, 1 = \u00faltimo, 2 = cualquiera\n                if l == 0: buf[a, k] = 0; k += 1\n                if l == n - 1: buf[a, k] = 1; k += 1\n                buf[a, k] = 2; k += 1\n            lens[a] = k; pos[a] = 0\n        while True:\n            f = 0\n            for a in range(A): f += buf[a, pos[a]] * strides[a]\n            e = evmap[f]\n            if e >= lo and e < hi:\n                ES[s, e - lo] += sv[p]; EC[s, e - lo] += cv[p]\n            a = A - 1\n            while a >= 0:\n                pos[a] += 1\n                if pos[a] < lens[a]: break\n                pos[a] = 0; a -= 1\n            if a < 0: break\n\n\ndef _rango_celdas(lv, niveles, modos):\n    \"\"\"Celda m\u00ednima y m\u00e1xima (por eje) que contiene a cada nivel crudo, seg\u00fan el modo (misma regla que `mascara`).\"\"\"\n    n = niveles[None, :]; m = modos[None, :]\n    cmin = np.select([m == 0, m == 1, m == 2, m == 3], [lv, 0, lv, lv], np.where(lv == 0, 0, np.where(lv == n - 1, 1, 2)))\n    cmax = np.select([m == 0, m == 1, m == 2, m == 3], [lv, lv, n - 1, n], 2)\n    return cmin.astype(np.int64), cmax.astype(np.int64)\n\n\nclass _Bootstrap:\n    \"\"\"Medias bootstrap de las celdas evaluables por bloques de columnas (ver arriba).\"\"\"\n\n    def __init__(self, perillas, indices, valores, ses_inv, n_ses, ev, W, bloque_bytes=None, memoria_bytes=None):\n        v = np.asarray(valores, float); ok = np.isfinite(v)\n        for p, ix in zip(perillas, indices): ok &= (np.asarray(ix) >= 0) & (np.asarray(ix) < p.niveles)\n        shp_raw = tuple(p.niveles for p in perillas); shp = tuple(p.tamano_celdas() for p in perillas)\n        flat = np.ravel_multi_index(tuple(np.asarray(ix)[ok] for ix in indices), shp_raw)\n        clave = np.asarray(ses_inv)[ok].astype(np.int64) * int(np.prod(shp_raw)) + flat\n        u, j = np.unique(clave, return_inverse=True)                 # pares (sesi\u00f3n, celda cruda)\n        self.sv = np.bincount(j, weights=v[ok], minlength=len(u)); self.cv = np.bincount(j, minlength=len(u)).astype(float)\n        ses_p = (u // int(np.prod(shp_raw))).astype(np.int64)             # u ordenado => pares ordenados por sesi\u00f3n\n        self.ses_ini = np.searchsorted(ses_p, np.arange(int(n_ses) + 1)).astype(np.int64)\n        self.lv = np.stack(np.unravel_index(u % int(np.prod(shp_raw)), shp_raw), 1).astype(np.int64) if len(u) else np.zeros((0, len(shp)), np.int64)\n        self.niveles = np.array([p.niveles for p in perillas], np.int64); self.modos = np.array([_MODOS[p.modo] for p in perillas], np.int64)\n        self.strides = (np.array([int(np.prod(shp[a + 1:])) for a in range(len(shp))], np.int64))\n        cmin, cmax = _rango_celdas(self.lv, self.niveles, self.modos)\n        self.fmin, self.fmax = cmin @ self.strides, cmax @ self.strides     # rango de celdas planas que puede tocar cada par\n        self.evflat = np.flatnonzero(ev)\n        self.n_ev = int(ev.sum()); self.evmap = np.full(ev.size, -1, np.int32 if self.n_ev < 2**31 else np.int64); self.evmap[self.evflat] = np.arange(self.n_ev)\n        self.W, self.n_ses = W, int(n_ses); B = W.shape[0]\n        bb = bloque_bytes or RW_BLOQUE_BYTES; mem = memoria_bytes or RW_MEMORIA_BYTES\n        self.ancho = max(1, min(self.n_ev, bb // (16 * max(self.n_ses, 1) + 8 * B)))\n        self.guardar = B * self.n_ev * 4 <= mem; self._cache = {}; self._std = None\n\n    def _sumas(self, a, b):\n        ES = np.zeros((self.n_ses, b - a)); EC = np.zeros((self.n_ses, b - a))\n        _expandir(self.ses_ini, self.lv, self.sv, self.cv, self.fmin, self.fmax, self.niveles, self.modos, self.strides, self.evmap, a, b,\n                  int(self.evflat[a]), int(self.evflat[b - 1]), ES, EC)\n        return ES, EC\n\n    def _medias(self, a, b):\n        ES, EC = self._sumas(a, b)\n        with np.errstate(invalid=\"ignore\", divide=\"ignore\"): return ((self.W @ ES) / (self.W @ EC)).astype(np.float32)\n\n    def bloque(self, a, b):\n        if (a, b) in self._cache: return self._cache[(a, b)]\n        M = self._medias(a, b)\n        if self._std is not None: m0, sd = self._std; M -= m0[a:b]; M /= sd[a:b]\n        if self.guardar: self._cache[(a, b)] = M\n        return M\n\n    def bloques(self):\n        for a in range(0, self.n_ev, self.ancho):\n            b = min(self.n_ev, a + self.ancho); yield a, b, self.bloque(a, b)\n\n    def estandarizar(self, m0, sd):\n        self._std = (m0, sd)\n        for (a, b), M in self._cache.items(): M -= m0[a:b]; M /= sd[a:b]\n\n    def maximo(self, activos):\n        \"\"\"max_j sobre las celdas activas de cada r\u00e9plica (NaN se ignora; sin activas: -inf), sin copiar la matriz entera.\"\"\"\n        out = np.full(self.W.shape[0], -np.inf, np.float32)\n        for a, b, M in self.bloques():\n            act = activos[a:b]\n            if not act.any(): continue\n            with np.errstate(invalid=\"ignore\"): out = np.fmax(out, np.nanmax(np.where(act, M, -np.inf), axis=1))\n        return out\n\n\ndef _medias_bootstrap_denso(perillas, indices, valores, ses_inv, ev, W):\n    \"\"\"Or\u00e1culo (la implementaci\u00f3n anterior): un tensor completo por r\u00e9plica.\"\"\"\n    M = np.empty((W.shape[0], int(ev.sum())), np.float32)\n    for b in range(W.shape[0]):\n        S, _, C = tensor(perillas, indices, valores, pesos=W[b][ses_inv])\n        with np.errstate(invalid=\"ignore\", divide=\"ignore\"): M[b] = (S.ravel() / C.ravel())[ev]\n    return M\n\n\n@njit(cache=False)\ndef _cola_superior_nb(t):\n    out = np.empty(len(t))\n    for i in range(len(t)): out[i] = 1.0 - 0.5 * (1.0 + math.erf(t[i] / math.sqrt(2.0)))     # = 1 - NormalDist().cdf(t) (f\u00f3rmula de 3.13)\n    return out\n\n\n@njit(cache=True)\ndef _betacf_nb(a, b, x):\n    \"\"\"Fracci\u00f3n continua de la beta incompleta (Lentz modificado), igual que `escalera._betacf`.\"\"\"\n    tiny = 1e-300\n    d = 1.0 - (a + b) * x / (a + 1.0)\n    if abs(d) < tiny: d = tiny\n    d = 1.0 / d; c = 1.0; h = d\n    for m in range(1, 500):\n        m2 = 2 * m\n        aa = m * (b - m) * x / ((a - 1 + m2) * (a + m2))\n        d = 1.0 + aa * d\n        if abs(d) < tiny: d = tiny\n        c = 1.0 + aa / c\n        if abs(c) < tiny: c = tiny\n        d = 1.0 / d; h *= d * c\n        aa = -(a + m) * (a + b + m) * x / ((a + m2) * (a + 1 + m2))\n        d = 1.0 + aa * d\n        if abs(d) < tiny: d = tiny\n        c = 1.0 + aa / c\n        if abs(c) < tiny: c = tiny\n        d = 1.0 / d; de = d * c; h *= de\n        if abs(de - 1.0) < 1e-15: break\n    return h\n\n\n@njit(cache=True)\ndef _cola_t_nb(t, gl):\n    out = np.empty(len(t))\n    for i in range(len(t)):\n        ti, g = t[i], gl[i]\n        if not np.isfinite(ti):\n            out[i] = 0.0 if ti > 0 else 1.0; continue\n        x = g / (g + ti * ti); a = g / 2.0; b = 0.5\n        if x <= 0.0: ib = 0.0\n        elif x >= 1.0: ib = 1.0\n        else:\n            lbt = math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b) + a * math.log(x) + b * math.log1p(-x)\n            if x < (a + 1.0) / (a + b + 2.0): ib = math.exp(lbt) * _betacf_nb(a, b, x) / a\n            else: ib = 1.0 - math.exp(lbt) * _betacf_nb(b, a, 1.0 - x) / b\n        cola = 0.5 * ib                                                    # = P(|T| > |t|) / 2\n        out[i] = cola if ti > 0 else 1.0 - cola\n    return out\n\n\ndef _cola_t_superior(t, gl):\n    \"\"\"P(T > t), T de Student con `gl` g.l., vectorizado (2026-11-03). Misma f\u00f3rmula que `escalera.t_cola_superior`.\"\"\"\n    return _cola_t_nb(np.ascontiguousarray(t, dtype=np.float64), np.ascontiguousarray(gl, dtype=np.float64))\n\n\ndef _cola_superior(t):\n    \"\"\"1 - Phi(t) vectorizado (antes: np.vectorize de NormalDist.cdf, una llamada Python por celda). Difiere a lo sumo en 1 ulp\n    (libm vs CPython; NormalDist mismo cambia de f\u00f3rmula entre versiones de Python): ning\u00fan corte del tamiz depende de eso.\"\"\"\n    return _cola_superior_nb(np.ascontiguousarray(t, dtype=np.float64))\n\ndef pistas(st, t, k=60, min_dif=2, min_n=30):\n    \"\"\"Las k mejores celdas por t (la de romano_wolf: agrupada por sesi\u00f3n) con media > 0, DISTINTAS entre s\u00ed: cada una difiere\n    de todas las elegidas en >= `min_dif` perillas (si no, ser\u00edan la misma estrategia con otro nombre). Son pistas para r\u00e9plica,\n    no hallazgos: lo que es azar muere en la r\u00e9plica.\"\"\"\n    tt = np.asarray(t).ravel(); ok = np.isfinite(tt) & (st[\"media\"].ravel() > 0) & (st[\"n\"].ravel() >= min_n)\n    elegidas = []\n    for f in np.flatnonzero(ok)[np.argsort(-tt[ok])]:\n        c = np.array(np.unravel_index(f, st[\"n\"].shape))\n        if all(int((c != e).sum()) >= min_dif for e in elegidas): elegidas.append(c)\n        if len(elegidas) >= k: break\n    return [tuple(int(v) for v in c) for c in elegidas]\n", "edgelab/funnel/escalera.py": "\"\"\"Escalera de promoci\u00f3n para estudios de evento y reglas con P&L por operaci\u00f3n (auditor\u00eda del embudo, 2026-10-22).\n\nPor qu\u00e9 existe. El runner del embudo s\u00f3lo cubre matrices se\u00f1al x (SL, TP); todo lo que se investig\u00f3 en la pr\u00e1ctica (impulsos,\nORB, escalonadas, reglas vistas en el visor) se midi\u00f3 con scripts sueltos, sin contador global ni una regla de decisi\u00f3n com\u00fan.\nY el ciclo aut\u00f3nomo decide con Holm (error familiar) al nivel que le deja el alpha-investing, que tras 8 campa\u00f1as qued\u00f3 en\nriqueza 0,0025: ya no puede descubrir nada aunque exista. Las dos cosas fallan en sentidos opuestos: los scripts sueltos no\ncuentan lo probado (sobreajuste) y el autopilot exige tanto que descarta lo que podr\u00eda funcionar (error de tipo II).\n\nDise\u00f1o, en dos niveles, como el descubrimiento + r\u00e9plica de la gen\u00f3mica (y Harvey-Liu-Zhu para finanzas):\n  1. TAMIZ masivo sobre la muestra de descubrimiento: FDR (Benjamini-Hochberg o Storey adaptativo) a q = 0,10 dentro de la\n     campa\u00f1a. Controla la FRACCI\u00d3N de nominaciones falsas, no la chance de una sola, as\u00ed que escala a miles de pruebas sin\n     matar la potencia. Nominar no afirma nada: s\u00f3lo da derecho a gastar una r\u00e9plica. Todo lo probado va al contador global.\n  2. CONFIRMACI\u00d3N en muestra no mirada: pocas pruebas (<= 3 por campa\u00f1a), cada una con nivel asignado por LORD++ (FDR en l\u00ednea,\n     Javanmard-Montanari 2018; Ramdas et al. 2017), que no se muere como el alpha-investing cuando hay rachas sin hallazgos.\n     La r\u00e9plica, el holdout y el paper se siguen con e-procesos (`secuencial.py`), v\u00e1lidos aunque se mire cada semana.\n  3. Tres salidas posibles por candidata, no dos: CONFIRMADA, REFUTADA (con evidencia: la cota optimista no llega a lo \u00fatil) y\n     SIN_POTENCIA (viva: el informe dice cu\u00e1ntas operaciones m\u00e1s hacen falta). Un nulo sin potencia no mata (ATJ-18, Harris 2016).\n  4. Realismo econ\u00f3mico antes de abrir el holdout: costos can\u00f3nicos (`edgelab/costos.py`), estr\u00e9s adverso, concentraci\u00f3n, y el\n     efecto ESPERADO fuera de muestra con recorte por selecci\u00f3n (DSR de Bailey-L\u00f3pez de Prado con N_eff; recorte de Sharpe de\n     Harvey-Liu). Abrir el holdout s\u00f3lo si con el n que va a dar hay potencia para ver el efecto recortado.\n\nNada de este m\u00f3dulo otorga estados G (contrato G0-G5): produce el nivel del embudo y la evidencia que G2-G4 piden.\n\"\"\"\nfrom __future__ import annotations\n\nimport bisect\nimport math\nfrom dataclasses import dataclass, field\nfrom statistics import NormalDist\n\nimport numpy as np\n\n_N = NormalDist()\nQ_TAMIZ = 0.10\nALFA_CONFIRMACION = 0.05\nESTADOS = (\"DESCARTADA_INTEGRIDAD\", \"REFUTADA\", \"SIN_POTENCIA\", \"NOMINADA\", \"CONFIRMADA_REPLICA\", \"LISTA_PARA_HOLDOUT\")\n\n\n# ----------------------------------------------------------------------------- 1. tamiz masivo (FDR dentro de la campa\u00f1a)\ndef tamiz_fdr(pvals, q: float = Q_TAMIZ, metodo: str = \"storey\", lam: float = 0.5) -> dict:\n    \"\"\"Benjamini-Hochberg (o Storey: BH con pi0 estimado, m\u00e1s potente cuando hay muchos efectos reales). V\u00e1lido con independencia\n    o dependencia positiva (PRDS); 'by' (Benjamini-Yekutieli) para dependencia arbitraria. Devuelve \u00edndices nominados y q-valores.\"\"\"\n    p = np.asarray(pvals, float)\n    if p.ndim != 1 or not len(p) or np.any(~np.isfinite(p)) or np.any((p < 0) | (p > 1)):\n        raise ValueError(\"p-valores finitos en [0,1]; las pruebas no evaluables se cuentan con p=1, no se omiten\")\n    m = len(p); pi0 = 1.0\n    if metodo == \"storey\":\n        pi0 = min(1.0, (np.sum(p > lam) + 1) / ((1 - lam) * m))\n    elif metodo == \"by\":\n        pi0 = sum(1.0 / i for i in range(1, m + 1))\n    elif metodo != \"bh\":\n        raise ValueError(\"metodo: bh | storey | by\")\n    o = np.argsort(p, kind=\"stable\"); ps = p[o] * m * pi0 / np.arange(1, m + 1)\n    qv = np.minimum.accumulate(ps[::-1])[::-1].clip(max=1.0)\n    qvals = np.empty(m); qvals[o] = qv\n    return dict(nominadas=sorted(int(i) for i in np.flatnonzero(qvals <= q)), q_valores=qvals.tolist(), pi0=float(pi0), q=q, metodo=metodo, m=m)\n\n\n# ----------------------------------------------------------------------------- 2. confirmaci\u00f3n: FDR en l\u00ednea (LORD++)\ndef _gamma_jm(j: int) -> float:\n    \"\"\"Secuencia de Javanmard-Montanari (suma exactamente 1 con la constante 0,07720838): pensada para miles de pruebas.\"\"\"\n    return 0.07720838 * math.log(max(j, 2)) / (j * math.exp(math.sqrt(math.log(j)))) if j >= 1 else 0.0\n\n\n_ZETA_16 = 2.2857491                       # zeta(1,6)\n\n\ndef _gamma_finita(j: int) -> float:\n    \"\"\"j^-1,6 / zeta(1,6): suma 1, m\u00e1s peso en las primeras pruebas. Para un proyecto con decenas o cientos de confirmaciones.\"\"\"\n    return j ** -1.6 / _ZETA_16 if j >= 1 else 0.0\n\n\nGAMMAS = {\"finita\": _gamma_finita, \"javanmard_montanari\": _gamma_jm}\n\n\n@dataclass\nclass LordPP:\n    \"\"\"LORD++ (Ramdas et al. 2017, sobre Javanmard-Montanari 2018): controla el FDR a nivel `alfa` sobre la secuencia de TODAS las\n    confirmaciones (r\u00e9plicas) de la historia del proyecto. El nivel de la prueba t depende de cu\u00e1ndo hubo descubrimientos previos;\n    tras una racha sin hallazgos decae lento (gamma ~ log j / j\u00b7e^sqrt(log j)) en vez de agotarse. Estado serializable (to_dict).\"\"\"\n    alfa: float = ALFA_CONFIRMACION\n    w0: float = ALFA_CONFIRMACION / 2\n    t: int = 0\n    rechazos: list = field(default_factory=list)       # \u00edndices t (1-based) de los descubrimientos\n    historia: list = field(default_factory=list)\n    gamma: str = \"finita\"                               # cualquier secuencia no negativa que sume <= 1 es v\u00e1lida; se fija ANTES de la primera prueba\n\n    def nivel(self) -> float:\n        t = self.t + 1; g = GAMMAS[self.gamma]\n        a = g(t) * self.w0\n        if self.rechazos:\n            a += (self.alfa - self.w0) * g(t - self.rechazos[0]) + self.alfa * sum(g(t - r) for r in self.rechazos[1:])\n        return a\n\n    def probar(self, p: float, etiqueta: str = \"\") -> dict:\n        if not 0 <= p <= 1: raise ValueError(\"p fuera de [0,1]\")\n        a = self.nivel(); self.t += 1; ok = p <= a\n        if ok: self.rechazos.append(self.t)\n        r = dict(t=self.t, etiqueta=etiqueta, p=p, nivel=a, rechazo=ok); self.historia.append(r); return r\n\n    def reservar(self, etiqueta: str = \"\") -> dict:\n        \"\"\"Consume el paso t AHORA con su nivel fijo, sin p todav\u00eda (decisi\u00f3n del 2026-10-24: el acta reserva su \u03b1 antes de mirar).\n        Mientras est\u00e1 pendiente cuenta como no rechazo para los pasos que siguen: s\u00f3lo puede dejarles menos nivel, nunca m\u00e1s\n        (LORD++ asincr\u00f3nico, Zrnic, Ramdas y Jordan 2021), as\u00ed que el FDR sigue controlado.\"\"\"\n        a = self.nivel(); self.t += 1\n        r = dict(t=self.t, etiqueta=etiqueta, p=None, nivel=a, rechazo=None, reservada=True); self.historia.append(r); return r\n\n    def resolver(self, t: int, p: float) -> dict:\n        \"\"\"Decide el paso reservado t al nivel que se fij\u00f3 al reservarlo.\"\"\"\n        if not 0 <= p <= 1: raise ValueError(\"p fuera de [0,1]\")\n        h = next((x for x in self.historia if x[\"t\"] == t), None)\n        if h is None or not h.get(\"reservada\"): raise ValueError(f\"el paso {t} no es una reserva\")\n        if h[\"rechazo\"] is not None: return h                                          # ya resuelta: idempotente\n        h.update(p=p, rechazo=bool(p <= h[\"nivel\"]))\n        if h[\"rechazo\"]: bisect.insort(self.rechazos, t)\n        return h\n\n    def to_dict(self) -> dict:\n        return dict(alfa=self.alfa, w0=self.w0, t=self.t, rechazos=list(self.rechazos), historia=list(self.historia), gamma=self.gamma, metodo=\"LORD++\")\n\n    @staticmethod\n    def from_dict(d: dict) -> \"LordPP\":\n        return LordPP(d[\"alfa\"], d[\"w0\"], d[\"t\"], list(d[\"rechazos\"]), list(d.get(\"historia\", [])), d.get(\"gamma\", \"finita\"))\n\n\n\ndef decidir_lote(nivel: float, pruebas: list) -> dict:\n    \"\"\"La decisi\u00f3n de un lote a un nivel YA asignado (Simes para la familia, BH adentro). La usa `probar_lote` y el libro cuando\n    resuelve un paso reservado por un acta (el nivel qued\u00f3 fijo al escribirla). pruebas: [(nombre, p)].\"\"\"\n    if not pruebas: return dict(nivel=nivel, p_simes=None, rechazo=False, confirmadas=[], m=0)\n    ps = np.array([float(p) for _, p in pruebas]); m = len(ps); o = np.argsort(ps, kind=\"stable\")\n    if np.any((ps < 0) | (ps > 1)): raise ValueError(\"p fuera de [0,1]\")\n    p_simes = float(min(1.0, np.min(ps[o] * m / np.arange(1, m + 1)))); rech = bool(p_simes <= nivel); conf = []\n    if rech:\n        ok = np.flatnonzero(ps[o] <= nivel * np.arange(1, m + 1) / m)\n        conf = [dict(test=pruebas[i][0], p=float(ps[i]), nivel=nivel) for i in o[:ok.max() + 1]] if len(ok) else []\n    return dict(nivel=nivel, p_simes=p_simes, rechazo=rech, confirmadas=conf, m=m)\n\n\ndef probar_lote(L: \"LordPP\", pruebas: list, etiqueta: str = \"\") -> dict:\n    \"\"\"Un LOTE de r\u00e9plicas simult\u00e1neas (las de una misma corrida) ocupa UN paso de LORD++ (Benjamini y Bogomolov 2014: primero\n    se selecciona la familia, despu\u00e9s se decide adentro). p de la familia = Simes (min_k p_(k)\u00b7m/k); si la familia rechaza al\n    nivel alfa_t de LORD++, BH dentro del lote a ese mismo nivel. Con una sola prueba es id\u00e9ntico a `L.probar`.\n    Error que corrige (2026-10-23): pasar 80 r\u00e9plicas de una corrida de a una por LORD++ gastaba el nivel en las primeras\n    (0,011 la 1.\u00aa, ~0 desde la 20.\u00aa) y la decisi\u00f3n depend\u00eda del orden alfab\u00e9tico. pruebas: [(nombre, p)].\"\"\"\n    if not pruebas: return dict(nivel=L.nivel(), p_simes=None, rechazo=False, confirmadas=[])\n    d = decidir_lote(L.nivel(), pruebas)\n    r = L.probar(d[\"p_simes\"], etiqueta or f\"lote de {d['m']}\")\n    return dict(d, t=r[\"t\"])\n\n# ----------------------------------------------------------------------------- 3. inferencia por operaci\u00f3n, agrupada por sesi\u00f3n\ndef resumen_sesiones(netos, sesiones, n_boot: int = 4000, seed: int = 20261022, confianza: float = 0.90) -> dict:\n    \"\"\"Media neta por operaci\u00f3n con IC bootstrap remuestreando SESIONES enteras (miles de operaciones en pocas sesiones no son\n    miles de apuestas independientes: ATJ-11). p unilateral de H0: media <= 0 por bootstrap centrado. Con < 160 sesiones el IC es\n    orientativo (el PrimaryCI estudentizado del contrato G2 exige 160).\"\"\"\n    x = np.asarray(netos, float); s = np.asarray(sesiones)\n    if x.ndim != 1 or len(x) != len(s) or not len(x) or not np.isfinite(x).all():\n        raise ValueError(\"netos y sesiones alineados, finitos y no vac\u00edos\")\n    u, inv = np.unique(s, return_inverse=True); tot = np.bincount(inv, weights=x); cnt = np.bincount(inv).astype(float)\n    k = len(u); obs = float(x.mean()); rng = np.random.default_rng(seed)\n    if n_boot * k <= _BLOQUE_BOOT:\n        pick = rng.integers(0, k, (n_boot, k)); T = tot[pick].sum(1); C = cnt[pick].sum(1); mb = T / C\n    else:                                                              # B grande (resoluci\u00f3n, 2026-10-24): por bloques, memoria acotada\n        mb = np.empty(n_boot); paso = max(1, _BLOQUE_BOOT // k)\n        for a in range(0, n_boot, paso):\n            pick = rng.integers(0, k, (min(paso, n_boot - a), k)); mb[a:a + len(pick)] = tot[pick].sum(1) / cnt[pick].sum(1)\n    cen = mb - obs                                                     # distribuci\u00f3n nula centrada\n    a = (1 - confianza) / 2\n    sd_ses = float(np.std(tot - obs * cnt, ddof=1)) if k > 1 else float(\"nan\")   # dispersi\u00f3n del aporte por sesi\u00f3n (influencia)\n    se = float(np.std(mb, ddof=1))\n    return dict(n_ops=int(len(x)), n_sesiones=int(k), ops_por_sesion=float(len(x) / k), media=obs, se=se,\n                ic=[float(np.quantile(mb, a)), float(np.quantile(mb, 1 - a))], confianza=confianza,\n                p_unilateral=float((1 + np.sum(cen >= obs)) / (n_boot + 1)), sd_por_op=float(np.std(x, ddof=1)) if len(x) > 1 else float(\"nan\"),\n                sd_aporte_sesion=sd_ses, ic_orientativo=bool(k < 160), metodo=\"bootstrap por sesiones (iid de sesiones)\")\n\n\n# ----------------------------------------------------------------------------- 3b. resoluci\u00f3n del p (falsos negativos, 2026-10-24)\n# El p del bootstrap no baja de 1/(B+1). Con B = 2000 el piso es 5e-4, y el nivel de LORD++ de una familia con historia baja a\n# 1e-5: rechazar era imposible por construcci\u00f3n y el \u00absin rechazo\u00bb se le\u00eda como evidencia (U1: 80 r\u00e9plicas a 2e-5 con p \u2265 5e-4).\n# Regla: B >= POR_NIVEL / umbral (umbral = nivel / m, el m\u00e1s exigente de Simes/BH en un lote de m), hasta N_BOOT_MAX; si no\n# alcanza, p anal\u00edtico agrupado por sesi\u00f3n (t de Student con k-1 g.l. sobre los aportes por sesi\u00f3n). Nunca un \u00abno rechaza\u00bb por\n# resoluci\u00f3n.\n_BLOQUE_BOOT = 8_000_000                   # elementos de la matriz de sorteo por bloque (~64 MB en int64)\nN_BOOT_BASE, N_BOOT_MAX, POR_NIVEL = 2000, 200_000, 10\n\n\ndef n_boot_para(nivel: float | None, m: int = 1, base: int = N_BOOT_BASE, tope: int = N_BOOT_MAX) -> int:\n    \"\"\"B necesario para resolver el umbral m\u00e1s exigente de un lote de m pruebas a `nivel` (>= POR_NIVEL r\u00e9plicas por umbral).\"\"\"\n    if nivel is None or not nivel > 0: return int(base)\n    return int(min(tope, max(base, math.ceil(POR_NIVEL * max(int(m), 1) / nivel))))\n\n\ndef _betacf(a: float, b: float, x: float) -> float:\n    \"\"\"Fracci\u00f3n continua de la beta incompleta (Lentz modificado, Numerical Recipes). Sin scipy: el n\u00facleo no suma dependencias.\"\"\"\n    tiny = 1e-300\n    def _no_cero(v): return v if abs(v) > tiny else tiny\n    c, d = 1.0, 1.0 / _no_cero(1.0 - (a + b) * x / (a + 1.0)); h = d\n    for m in range(1, 500):\n        m2 = 2 * m\n        aa = m * (b - m) * x / ((a - 1 + m2) * (a + m2))\n        d = 1.0 / _no_cero(1.0 + aa * d); c = _no_cero(1.0 + aa / c); h *= d * c\n        aa = -(a + m) * (a + b + m) * x / ((a + m2) * (a + 1 + m2))\n        d = 1.0 / _no_cero(1.0 + aa * d); c = _no_cero(1.0 + aa / c); de = d * c; h *= de\n        if abs(de - 1.0) < 1e-15: break\n    return h\n\n\ndef t_cola_superior(t: float, gl: float) -> float:\n    \"\"\"P(T > t) para una t de Student con `gl` grados de libertad (beta incompleta regularizada).\"\"\"\n    if not math.isfinite(t): return 0.0 if t > 0 else 1.0\n    x = gl / (gl + t * t); a, b = gl / 2.0, 0.5\n    lbt = math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b) + a * math.log(x) + b * math.log1p(-x) if 0 < x < 1 else None\n    if lbt is None: ib = 0.0 if x <= 0 else 1.0\n    elif x < (a + 1) / (a + b + 2): ib = math.exp(lbt) * _betacf(a, b, x) / a\n    else: ib = 1.0 - math.exp(lbt) * _betacf(b, a, 1 - x) / b\n    cola = 0.5 * ib                                                    # = P(|T| > |t|) / 2\n    return float(cola if t > 0 else 1.0 - cola)\n\n\ndef p_sesiones_analitico(netos, sesiones) -> dict:\n    \"\"\"p unilateral (H0: media <= 0) agrupado por sesi\u00f3n: t = media / se_cluster, se con los aportes por sesi\u00f3n (CR1, k/(k-1)),\n    referencia t de Student con k-1 g.l. Es la alternativa cuando el bootstrap no puede resolver el nivel.\"\"\"\n    x = np.asarray(netos, float); s = np.asarray(sesiones)\n    u, inv = np.unique(s, return_inverse=True); tot = np.bincount(inv, weights=x); cnt = np.bincount(inv).astype(float)\n    k = len(u); N = float(cnt.sum()); mu = float(tot.sum() / N)\n    if k < 2: return dict(p=1.0, t=float(\"nan\"), gl=0, metodo=\"anal\u00edtico por sesi\u00f3n (sin g.l.)\")\n    e = tot - mu * cnt; se = math.sqrt(k / (k - 1) * float(np.sum(e * e))) / N\n    t = mu / se if se > 0 else (math.inf if mu > 0 else -math.inf)\n    return dict(p=t_cola_superior(t, k - 1), t=float(t), gl=k - 1, metodo=\"anal\u00edtico por sesi\u00f3n (t de Student, k-1 g.l.)\")\n\n\ndef resumen_resuelto(netos, sesiones, nivel: float | None = None, m: int = 1, n_boot: int = N_BOOT_BASE, seed: int = 20261022) -> dict:\n    \"\"\"`resumen_sesiones` con un p que puede resolver el umbral `nivel / m`: sube B (>= 10 por umbral, hasta N_BOOT_MAX) y, si no\n    alcanza, usa el p anal\u00edtico por sesi\u00f3n. Publica `n_boot`, `piso_p` y `metodo_p`. Sin nivel: igual que antes.\"\"\"\n    B = n_boot_para(nivel, m, base=n_boot)\n    necesita = nivel is not None and nivel > 0 and POR_NIVEL * max(int(m), 1) / nivel > N_BOOT_MAX\n    rs = resumen_sesiones(netos, sesiones, n_boot=B, seed=seed)\n    rs.update(n_boot=B, piso_p=1.0 / (B + 1), metodo_p=\"bootstrap por sesiones\")\n    if necesita:\n        an = p_sesiones_analitico(netos, sesiones)\n        rs.update(p_bootstrap=rs[\"p_unilateral\"], p_unilateral=an[\"p\"], metodo_p=an[\"metodo\"], t_sesiones=an[\"t\"], piso_p=0.0)\n    return rs\n\n\ndef mde(se: float, alfa: float = ALFA_CONFIRMACION, potencia: float = 0.8) -> float:\n    \"\"\"Efecto m\u00ednimo detectable (unilateral) con este error est\u00e1ndar.\"\"\"\n    return (_N.inv_cdf(1 - alfa) + _N.inv_cdf(potencia)) * se\n\n\ndef ops_necesarias(efecto: float, se_actual: float, n_actual: int, alfa: float = ALFA_CONFIRMACION, potencia: float = 0.8) -> int | None:\n    \"\"\"Operaciones para detectar `efecto` con la dispersi\u00f3n observada (se ~ 1/sqrt(n), conservando la agrupaci\u00f3n por sesi\u00f3n).\"\"\"\n    if efecto <= 0 or not math.isfinite(se_actual) or se_actual <= 0: return None\n    z = _N.inv_cdf(1 - alfa) + _N.inv_cdf(potencia)\n    return int(math.ceil(n_actual * (z * se_actual / efecto) ** 2))\n\n\ndef potencia(efecto: float, se: float, alfa: float = ALFA_CONFIRMACION) -> float:\n    if not math.isfinite(se) or se <= 0: return float(\"nan\")\n    return float(1 - _N.cdf(_N.inv_cdf(1 - alfa) - efecto / se))\n\n\n# ----------------------------------------------------------------------------- 4. recorte por selecci\u00f3n\ndef n_efectivo(matriz) -> float:\n    \"\"\"N\u00famero efectivo de pruebas a partir de la correlaci\u00f3n de sus P&L (Li y Ji 2005, sobre autovalores): variantes casi iguales\n    no cuentan como pruebas independientes. matriz: observaciones (p. ej. d\u00edas) x pruebas.\"\"\"\n    M = np.asarray(matriz, float)\n    if M.ndim != 2 or M.shape[1] < 2: return float(M.shape[1] if M.ndim == 2 else 1)\n    M = M[:, np.nanstd(M, 0) > 0]\n    if M.shape[1] < 2: return float(M.shape[1])\n    ev = np.clip(np.linalg.eigvalsh(np.corrcoef(np.nan_to_num(M), rowvar=False)), 0, None)\n    return float(sum((e >= 1) + (e - math.floor(e)) for e in ev))\n\n\ndef n_efectivo_o_bruto(n_bruto: float, matriz=None) -> dict:\n    \"\"\"N\u00famero de pruebas a cobrar (2026-10-24, falsos negativos): Li-Ji sobre la matriz de P&L (observaciones x pruebas) cuando\n    est\u00e1 disponible y cubre TODAS las pruebas contadas; si no, el bruto con aviso (nunca se extrapola Li-Ji de una muestra de\n    columnas a un total mayor: el descuento quedar\u00eda sin respaldo). Nunca devuelve m\u00e1s que el bruto.\"\"\"\n    n_bruto = float(n_bruto)\n    if matriz is None:\n        return dict(n=n_bruto, bruto=n_bruto, metodo=\"bruto\", aviso=\"sin matriz de P&L: se cobra el n\u00famero bruto (Li-Ji no aplicable)\")\n    M = np.asarray(matriz, float)\n    if M.ndim != 2 or M.shape[1] != int(n_bruto):\n        return dict(n=n_bruto, bruto=n_bruto, metodo=\"bruto\",\n                    aviso=f\"matriz de P&L con {M.shape[1] if M.ndim == 2 else 0} columnas para {int(n_bruto)} pruebas: se cobra el bruto\")\n    ne = min(n_efectivo(M), n_bruto)\n    return dict(n=float(max(ne, 1.0)), bruto=n_bruto, metodo=\"Li-Ji (autovalores de la correlaci\u00f3n de P&L)\", aviso=None)\n\n\ndef recorte_t(t: float, n_pruebas: float) -> dict:\n    \"\"\"Recorte de Harvey-Liu (2015) con Bonferroni sobre N_eff: el t observado (agrupado por sesi\u00f3n) se lleva al t que tendr\u00eda la\n    misma p ajustada. No lineal: castiga mucho a los marginales y poco a los muy fuertes. `conservado` = fracci\u00f3n del efecto que\n    se espera ver fuera de muestra por sesgo de selecci\u00f3n (no incluye decaimiento del mercado: McLean-Pontiff ~26 % adicional).\"\"\"\n    if not t > 0: return dict(t=t, t_ajustado=0.0, conservado=0.0, p_ajustada=1.0, metodo=\"Harvey-Liu, Bonferroni sobre N_eff\")\n    p = 1 - _N.cdf(t); pa = min(1.0, p * max(n_pruebas, 1.0))\n    ta = max(_N.inv_cdf(1 - pa), 0.0) if pa < 1 else 0.0\n    return dict(t=t, t_ajustado=ta, p_ajustada=pa, conservado=ta / t, metodo=\"Harvey-Liu, Bonferroni sobre N_eff\")\n\n\ndef dsr(sr_por_op: float, n_ops: int, n_pruebas: float, skew: float = 0.0, kurt: float = 3.0) -> float:\n    from edgelab.research.g2 import deflated_sharpe\n    return float(deflated_sharpe(sr_por_op, n_ops, max(n_pruebas, 1.0), skew, kurt))\n\n\n# ----------------------------------------------------------------------------- 5. realismo econ\u00f3mico\ndef economia(netos_base, netos_adverso=None, sesiones=None, periodos=None) -> dict:\n    \"\"\"G1/G3 sobre P&L NETO por operaci\u00f3n (costos can\u00f3nicos ya aplicados). Duros: neto base > 0; sin las 5 mejores > 0; ning\u00fan\n    per\u00edodo VIEJO > 80 % del total; adverso > -0,5 x base. Blando: margen < 1 tick (la decisi\u00f3n depende del modelo de costos).\n    R\u00e9gimen (principio de Nico, 2026-10-22: \u00abqueremos edges actuales, aunque en el pasado no hayan funcionado\u00bb): si la ganancia\n    se concentra en los per\u00edodos M\u00c1S RECIENTES (el \u00faltimo cuarto, al menos uno; `periodos` deben ordenar cronol\u00f3gicamente) no\n    se mata: se marca `regimen_reciente` y la confirmaci\u00f3n tiene que salir de datos posteriores (r\u00e9plica reciente o forward).\n    Concentrada en un per\u00edodo viejo sigue siendo dura: un edge que s\u00f3lo funcion\u00f3 antes no es actual.\"\"\"\n    x = np.asarray(netos_base, float); tot = float(x.sum()); r = dict(neto_base_por_op=float(x.mean()), neto_total=tot)\n    r[\"sin_top5_por_op\"] = float(np.sort(x)[:-5].mean()) if len(x) > 5 else float(\"nan\")\n    duros = dict(neto_base_positivo=bool(x.mean() > 0), sin_top5_positivo=bool(len(x) > 5 and np.sort(x)[:-5].sum() > 0))\n    if periodos is not None:\n        per = {}\n        for k, v in zip(periodos, x): per[k] = per.get(k, 0.0) + float(v)\n        r[\"por_periodo\"] = per; r[\"periodos_positivos\"] = f\"{sum(v > 0 for v in per.values())}/{len(per)}\"\n        orden = sorted(per); recientes = set(orden[-max(1, round(len(orden) / 4)):]); top = max(per, key=per.get)\n        concentrado = bool(tot > 0 and per[top] > 0.8 * tot)\n        r[\"regimen_reciente\"] = bool(concentrado and top in recientes)\n        duros[\"ningun_periodo_80pct\"] = bool(tot > 0 and (not concentrado or r[\"regimen_reciente\"]))\n    if netos_adverso is not None:\n        a = float(np.mean(netos_adverso)); r[\"neto_adverso_por_op\"] = a\n        duros[\"sin_colapso_adverso\"] = bool(a > -0.5 * x.mean()) if x.mean() > 0 else False\n    r[\"duros\"] = duros; r[\"pasa\"] = all(duros.values())\n    return r\n\n\n# ----------------------------------------------------------------------------- 6. veredicto\n@dataclass\nclass Veredicto:\n    estado: str\n    motivos: list\n    siguiente_paso: str\n    numeros: dict\n\n    def to_dict(self) -> dict:\n        return dict(estado=self.estado, motivos=self.motivos, siguiente_paso=self.siguiente_paso, numeros=self.numeros,\n                    asserts_edge=False, otorga_estado_G=False)\n\n\ndef evaluar(*, descubrimiento: dict, nominada: bool, n_pruebas_familia: float, efecto_util: float = 0.0,\n            replica: dict | None = None, alfa_replica: float | None = None, economico: dict | None = None,\n            n_esperado_holdout: int | None = None, integridad: list | None = None, pista_replicada: bool = False) -> Veredicto:\n    \"\"\"descubrimiento/replica: salidas de `resumen_sesiones` sobre P&L NETO por operaci\u00f3n. nominada: si pas\u00f3 `tamiz_fdr` en su\n    campa\u00f1a. n_pruebas_familia: N_eff cobrado (contador de la familia). efecto_util: neto m\u00ednimo por operaci\u00f3n que la vuelve \u00fatil\n    (0 = cualquier positivo). alfa_replica: nivel asignado por LORD++. n_esperado_holdout: operaciones que dar\u00e1 el holdout.\n    pista_replicada: la celda NO fue nominada pero entr\u00f3 por \u00abpistas a r\u00e9plica\u00bb (ATJ-25): congelada entre las top-k de su campa\u00f1a\n    ANTES de la r\u00e9plica, registrada en el contador y probada en lote con UN paso de LORD++ (`elegir_pistas_replica` +\n    `probar_lote`). Esa r\u00e9plica en datos no mirados es una confirmaci\u00f3n v\u00e1lida a su nivel (2026-10-24, falsos negativos).\"\"\"\n    if integridad:\n        return Veredicto(\"DESCARTADA_INTEGRIDAD\", list(integridad), \"corregir integridad (costos, entrada, look-ahead) y volver a medir: no hay lectura estad\u00edstica posible\", {})\n    d = descubrimiento; sr = d[\"media\"] / d[\"sd_por_op\"] if d[\"sd_por_op\"] and d[\"sd_por_op\"] > 0 else 0.0\n    rc = recorte_t(d[\"media\"] / d[\"se\"] if d[\"se\"] > 0 else 0.0, n_pruebas_familia); esperado = max(0.0, rc[\"conservado\"] * d[\"media\"])\n    num = dict(descubrimiento=d, recorte=rc, efecto_esperado_fuera_de_muestra=esperado, dsr=dsr(sr, d[\"n_ops\"], n_pruebas_familia),\n               n_pruebas_familia=n_pruebas_familia, mde_descubrimiento=mde(d[\"se\"]))\n    if economico is not None: num[\"economico\"] = economico            # se informa siempre, aunque el estado se decida antes\n    umbral = max(efecto_util, 0.0)\n    if d[\"ic\"][1] < umbral:\n        return Veredicto(\"REFUTADA\", [f\"la cota optimista del IC ({d['ic'][1]:.4g}) no llega al efecto \u00fatil ({umbral:.4g})\"],\n                         \"archivar con su alcance exacto (regla, poblaci\u00f3n, costos); no reintentar la misma hip\u00f3tesis sin campa\u00f1a nueva\", num)\n    if replica is None:\n        if not nominada:\n            faltan = ops_necesarias(max(d[\"media\"], mde(d[\"se\"]) / 2), d[\"se\"], d[\"n_ops\"])\n            sig = (\"queda viva en reserva: entra a \u00abpistas a r\u00e9plica\u00bb (top-k de la campa\u00f1a por cota inferior, congeladas, un paso de \"\n                   \"LORD++ por lote en una ventana reciente no usada)\")\n            return Veredicto(\"SIN_POTENCIA\", [f\"no pasa el tamiz FDR de su campa\u00f1a, pero el IC [{d['ic'][0]:.4g}, {d['ic'][1]:.4g}] no excluye lo \u00fatil\",\n                                              f\"MDE actual {num['mde_descubrimiento']:.4g} por operaci\u00f3n\"],\n                             sig + (f\"; con ~{faltan} operaciones se distinguir\u00eda el efecto observado del cero\" if faltan else \"\"), num)\n        return Veredicto(\"NOMINADA\", [\"pas\u00f3 el tamiz FDR de su campa\u00f1a (nominaci\u00f3n, no evidencia)\"],\n                         f\"pre-registrar la regla exacta y replicar en muestra no mirada; para ver el efecto recortado ({esperado:.4g}) hacen falta \"\n                         f\"~{ops_necesarias(esperado, d['se'], d['n_ops']) or 'inf'} operaciones con la dispersi\u00f3n actual\", num)\n    r = replica; num[\"replica\"] = r; a = alfa_replica if alfa_replica is not None else ALFA_CONFIRMACION; num[\"alfa_replica\"] = a\n    num[\"via\"] = \"nominada_fdr\" if nominada else (\"pista_replicada\" if pista_replicada else None)\n    if not nominada and not pista_replicada:            # decisi\u00f3n del 2026-10-24: sin nominaci\u00f3n FDR ni pista congelada, no hay confirmaci\u00f3n\n        return Veredicto(\"SIN_POTENCIA\", [\"no pas\u00f3 el tamiz FDR (q 0,10) de su campa\u00f1a ni entr\u00f3 como pista congelada a r\u00e9plica: la r\u00e9plica \"\n                                          \"no puede confirmarla (docs/research/revision_20261024/DECISIONES_VALIDACION_20261024.md)\"],\n                         \"queda viva en reserva: congelarla entre las top-k de su campa\u00f1a y replicarla en lote (pistas a r\u00e9plica, ATJ-25)\", num)\n    if r[\"p_unilateral\"] <= a and r[\"media\"] > 0:\n        est, mot = \"CONFIRMADA_REPLICA\", [f\"r\u00e9plica p = {r['p_unilateral']:.4g} <= nivel LORD++ {a:.4g}\"]\n    elif r[\"ic\"][1] < umbral:\n        return Veredicto(\"REFUTADA\", [f\"en la r\u00e9plica la cota optimista ({r['ic'][1]:.4g}) no llega a lo \u00fatil ({umbral:.4g})\"],\n                         \"archivar: la r\u00e9plica limpia la refuta\", num)\n    else:\n        faltan = ops_necesarias(esperado or r[\"media\"], r[\"se\"], r[\"n_ops\"], a)\n        return Veredicto(\"SIN_POTENCIA\", [f\"r\u00e9plica no concluyente (p = {r['p_unilateral']:.4g}, potencia para el efecto esperado \"\n                                          f\"{potencia(esperado, r['se'], a):.2f})\"],\n                         f\"seguir la r\u00e9plica con el monitor secuencial (secuencial.MonitorCandidato) hasta ~{faltan} operaciones; no abrir el holdout todav\u00eda\", num)\n    if economico is None:\n        return Veredicto(est, mot + [\"falta el chequeo econ\u00f3mico (G1/G3)\"], \"correr `economia` con costos can\u00f3nicos y escenario adverso\", num)\n    num[\"economico\"] = economico\n    if not economico[\"pasa\"]:\n        return Veredicto(est, mot + [\"no pasa lo econ\u00f3mico: \" + \", \".join(k for k, v in economico[\"duros\"].items() if not v)],\n                         \"nivel B: replica pero no es operable as\u00ed; corregir forma (costos, frecuencia, salidas) o usarla como filtro\", num)\n    if n_esperado_holdout is not None:\n        se_h = r[\"se\"] * math.sqrt(r[\"n_ops\"] / max(n_esperado_holdout, 1)); pot = potencia(esperado, se_h, ALFA_CONFIRMACION)\n        num[\"potencia_holdout\"] = pot\n        if not pot >= 0.8:\n            return Veredicto(est, mot + [f\"con {n_esperado_holdout} operaciones el holdout tiene potencia {pot:.2f} para el efecto recortado\"],\n                             \"esperar m\u00e1s datos sellados antes de la \u00fanica apertura, o seguirlo como paper con el monitor secuencial\", num)\n    return Veredicto(\"LISTA_PARA_HOLDOUT\", mot + [\"econ\u00f3mico OK\", \"potencia de holdout suficiente\"],\n                     \"apertura \u00fanica por protocolo (holdout_apertura) con la regla congelada; seguimiento secuencial\", num)\n\n\n# ----------------------------------------------------------------------------- 6b. pistas a r\u00e9plica (ATJ-25, restaurada 2026-10-24)\nK_PISTAS_REPLICA = 20\n\n\ndef elegir_pistas_replica(pistas: list, k: int = K_PISTAS_REPLICA, *, min_dif: int = 2, min_sesiones: int = 0,\n                          ratio_mov_friccion: float = 0.0) -> list:\n    \"\"\"Las top-k pistas de una campa\u00f1a que no nomin\u00f3 nada por FDR, para congelarlas y replicarlas en lote. Orden: cota inferior del\n    IC90 por sesiones (desc), desempate por t de Romano-Wolf; NUNCA por P&L m\u00e1ximo. Distintas entre s\u00ed (difieren en >= `min_dif`\n    perillas, tambi\u00e9n entre canales). Los filtros de relevancia son los de la selecci\u00f3n pre-registrada. S\u00f3lo entran pistas con cota\n    inferior del IC90 > 0 (2026-10-25): con Simes cada pista de m\u00e1s divide el nivel del lote, y una que ya cruza cero en el\n    descubrimiento casi no puede confirmar; dejarla entrar le quita potencia a las buenas (EXPZ: 17 pistas con cota negativa).\"\"\"\n    ok = [p for p in pistas if p.get(\"ic90\") and float(p[\"ic90\"][0]) > 0 and (p.get(\"media_neta\") or 0) > 0 and (p.get(\"sesiones\") or 0) >= min_sesiones\n          and (p.get(\"ratio_mov_friccion\") if p.get(\"ratio_mov_friccion\") is not None else float(\"inf\")) >= ratio_mov_friccion]\n    ok = sorted(ok, key=lambda p: (-float(p[\"ic90\"][0]), -float(p.get(\"t_rw\") or 0.0)))\n    out = []\n    for p in ok:\n        if any(sum(a != b for a, b in zip(p[\"celda\"], q[\"celda\"])) < min_dif for q in out): continue\n        out.append(p)\n        if len(out) >= k: break\n    return out\n\n\ndef decidir_pistas(dec_lote: dict, replica: list, nombres: list) -> list:\n    \"\"\"Qu\u00e9 pistas pasan a nominadas tras el paso de LORD++ del lote: confirmadas por BH dentro del lote (al nivel del paso) Y con\n    media neta > 0 en la r\u00e9plica. Devuelve los \u00edndices (en el orden de `replica`).\"\"\"\n    conf = {c[\"test\"] for c in (dec_lote or {}).get(\"confirmadas\", [])} if (dec_lote or {}).get(\"rechazo\") else set()\n    return [i for i, (n, r) in enumerate(zip(nombres, replica)) if n in conf and (r.get(\"media_neta\") or 0) > 0]\n\n\ndef canasta_pistas(operaciones: dict, k: int, n_boot: int = 4000) -> dict:\n    \"\"\"Prueba AGREGADA de un lote de pistas (decisi\u00f3n de Nico, 2026-10-26, auditor\u00eda del filtro): la canasta igual-ponderada de las k\n    pistas, P&L neto medio por pista y sesi\u00f3n, como UNA serie (bootstrap por sesiones). Detecta un edge repartido en muchas celdas vecinas\n    d\u00e9biles que la prueba pista por pista (umbral / k) no puede ver. `operaciones`: dict de listas con celda, ses, neto (REP).\"\"\"\n    import pandas as pd\n    o = pd.DataFrame(operaciones or {})\n    if not len(o): return dict(n_sesiones=0)\n    g = o.groupby([\"ses\", \"celda\"]).neto.sum().unstack().reindex(columns=range(k)).fillna(0.0).mean(axis=1)\n    rs = resumen_sesiones(g.to_numpy(float), g.index.to_numpy(), n_boot=n_boot)\n    return dict(n_sesiones=int(len(g)), media=float(g.mean()), ic90=rs[\"ic\"], p=rs[\"p_unilateral\"], n_boot=n_boot)\n\n\ndef veredicto_pistas(confirmadas: list, canasta: dict, dec_canasta: dict | None, media_desc: float, fraccion_efecto: float = 0.5,\n                     potencia_min: float = 0.8) -> dict:\n    \"\"\"Veredicto del lote de pistas (2026-10-26). Antes: 0 confirmadas una por una = SIN_CANDIDATAS, aunque la potencia fuera del 1\u20132 %.\n    Ahora, con la misma sem\u00e1ntica que el OOS (decisi\u00f3n 2 del 2026-10-24: un nulo sin potencia no mata):\n      CANASTA_CONFIRMADA   el paso de LORD++ de la canasta rechaza y su media > 0\n      PISTAS_CONFIRMADAS   alguna pista individual confirmada (como antes)\n      REFUTADA             la canasta tiene potencia >= potencia_min para fraccion_efecto x media del DESC y su IC90 entero es < 0\n      SIN_RECHAZO          con potencia, sin confirmar ni estar en contra: viva (un efecto menor que el del DESC sigue posible)\n      SIN_POTENCIA         sin potencia: viva. En los dos casos el pr\u00f3ximo paso es el holdout de la canasta congelada.\"\"\"\n    if dec_canasta and dec_canasta.get(\"rechazo\") and (canasta.get(\"media\") or 0) > 0: return dict(veredicto=\"CANASTA_CONFIRMADA\")\n    if confirmadas: return dict(veredicto=\"PISTAS_CONFIRMADAS\")\n    ic = canasta.get(\"ic90\")\n    if not ic: return dict(veredicto=\"SIN_POTENCIA\", motivo=\"canasta sin operaciones evaluables\")\n    se = (ic[1] - ic[0]) / (2 * 1.6448536); ef = fraccion_efecto * max(media_desc, 0.0)\n    nivel = (dec_canasta or {}).get(\"nivel\", ALFA_CONFIRMACION)\n    pot = potencia(ef, se, nivel) if ef > 0 else 0.0\n    if pot == pot and pot >= potencia_min and ic[1] < 0:\n        return dict(veredicto=\"REFUTADA\", potencia=pot, efecto=ef, motivo=\"canasta en contra con potencia\")\n    if pot == pot and pot >= potencia_min:\n        return dict(veredicto=\"SIN_RECHAZO\", potencia=pot, efecto=ef,\n                    motivo=(f\"con potencia para {fraccion_efecto:g} x el efecto del DESC: la canasta no lo alcanza (IC90 {ic}) pero no est\u00e1 en contra; \"\n                            \"un efecto menor sigue posible: la familia sigue viva\"))\n    return dict(veredicto=\"SIN_POTENCIA\", potencia=pot, efecto=ef,\n                motivo=\"ni pistas ni canasta confirman y no hay potencia para decidir: la familia sigue viva\")\n\n\ndef confirmar_en_canasta_regimen(netos_holdout, *, mu_esperada: float, sd_op_ref: float, z_banda: float = 1.6448536, n_min: int = 5) -> dict:\n    \"\"\"Confirmaci\u00f3n de una candidata para a\u00f1adir a una canasta de estrategias de r\u00e9gimen en un per\u00edodo reducido de holdout\n    (2026-10-27, decisi\u00f3n de Nico: como un edge real probablemente sea de r\u00e9gimen, no se puede esperar a\u00f1os a acumular n_fijo=150..450\n    individual porque el r\u00e9gimen terminar\u00eda; el riesgo se diversifica en la canasta y cada estrategia se confirma si su rendimiento\n    observado en el per\u00edodo reducido de holdout est\u00e1 dentro de la desviaci\u00f3n esperada seg\u00fan su distribuci\u00f3n previa).\n\n    Con `n` operaciones observadas en el holdout reducido:\n      - error est\u00e1ndar esperado para la media de `n` operaciones: `se_n = sd_op_ref / sqrt(n)`;\n      - banda esperada (90 % bilateral / 95 % inferior por defecto con `z_banda = 1.645`): `[mu_esperada - z_banda * se_n, mu_esperada + z_banda * se_n]`;\n      - `z_desvio = (media_obs - mu_esperada) / se_n`: cu\u00e1ntas desviaciones est\u00e1ndar se aparta de la media esperada;\n      - `dentro_desviacion`: `media_obs >= cota_inferior` (no cae por debajo de la desviaci\u00f3n inferior esperada para ese `n`);\n      - `confirmada_canasta`: `n >= 1` y `dentro_desviacion` (apta para a\u00f1adir a la canasta de r\u00e9gimen).\n    \"\"\"\n    x = np.asarray(netos_holdout, float); x = x[np.isfinite(x)]; n = int(len(x))\n    if n == 0 or not math.isfinite(sd_op_ref) or sd_op_ref <= 0:\n        return dict(n=n, media_obs=None, mu_esperada=float(mu_esperada), sd_op_ref=float(sd_op_ref), se_esperado=None,\n                    banda_esperada=None, z_desvio=None, dentro_desviacion=None, confirmada_canasta=False,\n                    estado=\"SIN_OPERACIONES_AUN\" if n == 0 else \"NO_EVALUABLE\")\n    obs = float(x.mean()); se_n = float(sd_op_ref) / math.sqrt(n)\n    lo, hi = float(mu_esperada) - z_banda * se_n, float(mu_esperada) + z_banda * se_n\n    z = (obs - float(mu_esperada)) / se_n\n    dentro = bool(obs >= lo)\n    # 2026-10-30 (auditor\u00eda): con n chico la banda inferior queda muy por debajo de 0 y \u00abdentro\u00bb aceptaba medias negativas\n    # (CVGAP-NQ: \u03bc 19, sd \u2248 100, n = 3 -> cota \u221276: una media de \u221250 sal\u00eda CONFIRMADA_CANASTA). Ahora la estrategia s\u00f3lo es apta si,\n    # adem\u00e1s, gana en el holdout (media > 0) con al menos `n_min` operaciones. Por debajo de la banda sigue saliendo (REFUTADA);\n    # el resto queda SIN_EVIDENCIA_AUN, sin matar la familia. La confirmaci\u00f3n con poco N es la de la CANASTA (`confirmar_canasta`).\n    apta = bool(dentro and obs > 0 and n >= n_min)\n    estado = \"FUERA_DE_BANDA_INFERIOR\" if not dentro else (\"CONFIRMADA_CANASTA\" if apta else \"SIN_EVIDENCIA_AUN\")\n    return dict(n=n, media_obs=obs, total_obs=float(x.sum()), mu_esperada=float(mu_esperada), sd_op_ref=float(sd_op_ref),\n                se_esperado=se_n, banda_esperada=[lo, hi], z_banda=float(z_banda), z_desvio=float(z), n_min=int(n_min),\n                dentro_desviacion=dentro, confirmada_canasta=apta, estado=estado)\n\n\ndef confirmar_canasta(miembros, *, z_inf: float = 0.8416212) -> dict:\n    \"\"\"Prueba \u00daNICA de una canasta de r\u00e9gimen congelada antes del holdout (2026-10-30). `miembros`: lista de dict(cid, netos, sd_op_ref)\n    con las operaciones netas de cada estrategia en el holdout y su sd por operaci\u00f3n de referencia (pre-holdout). Cada estrategia pesa\n    igual en riesgo: sus operaciones se dividen por su sd_op_ref (unidades de \u00abuna operaci\u00f3n t\u00edpica\u00bb). La canasta se confirma si la\n    media estandarizada combinada es > 0 con cota inferior unilateral al 80 % (z_inf = 0,8416) > 0. Junta el N de todas: con 12\n    estrategias y 3\u20135 operaciones cada una alcanza lo que ninguna sola alcanza.\"\"\"\n    zs, por, ses = [], {}, []\n    for m in miembros:\n        x = np.asarray(m.get(\"netos\") or [], float); x = x[np.isfinite(x)]; sd = float(m.get(\"sd_op_ref\") or 0)\n        if not len(x) or not math.isfinite(sd) or sd <= 0: por[m[\"cid\"]] = dict(n=int(len(x)), media_std=None); continue\n        zz = x / sd; zs.append(zz)\n        if m.get(\"ses\") is not None: ses.append(np.asarray(m[\"ses\"], np.int64)[np.isfinite(np.asarray(m[\"netos\"], float))])\n        por[m[\"cid\"]] = dict(n=int(len(x)), media_std=float(zz.mean()))\n    if not zs: return dict(n=0, media_std=None, cota_inf=None, confirmada=False, estado=\"SIN_OPERACIONES_AUN\", por_estrategia=por)\n    z = np.concatenate(zs); n = int(len(z)); mu = float(z.mean()); se = float(z.std(ddof=1) / math.sqrt(n)) if n > 1 else float(\"inf\")\n    if ses and len(ses) == len(zs):                                    # 2026-10-30: las reglas del mismo d\u00eda se correlacionan: el error va por sesi\u00f3n\n        sa = np.concatenate(ses); u, inv = np.unique(sa, return_inverse=True); dia = np.bincount(inv, weights=z)\n        se_d = float(dia.std(ddof=1) / math.sqrt(len(dia))) if len(dia) > 1 else float(\"inf\")\n        se = se_d * len(dia) / n                                       # el mismo t por sesi\u00f3n, en escala de media por operaci\u00f3n\n    lo = mu - z_inf * se\n    ok = bool(mu > 0 and lo > 0)\n    return dict(n=n, media_std=mu, se=se, cota_inf=lo, z_inf=float(z_inf), confirmada=ok,\n                estado=\"CANASTA_CONFIRMADA\" if ok else (\"CANASTA_EN_CONTRA\" if mu + z_inf * se < 0 else \"SIN_EVIDENCIA_AUN\"), por_estrategia=por)\n\n\n# ----------------------------------------------------------------------------- 7. puente con el ciclo aut\u00f3nomo\ndef para_autopilot(pruebas: list) -> dict:\n    \"\"\"Formato `results_flat` que `edgelab.autopilot.analyze.records` ya entiende (no hay que tocar el autopilot para leerlo).\n    pruebas: [{test, p, evaluable, effect}]; las de r\u00e9plica deben llevar '/rep/' en el nombre (analyze exige rechazo en r\u00e9plica).\"\"\"\n    return dict(results_flat=[dict(test=t[\"test\"], p=float(t[\"p\"]) if t.get(\"p\") is not None else None, evaluable=bool(t.get(\"evaluable\", True)),\n                                   diff=t.get(\"effect\")) for t in pruebas], schema=\"escalera_embudo_v1\")\n", "edgelab/research/g2.py": "\"\"\"G2 \u2014 Robustez estad\u00edstica. Implementa `docs/edge_validation_contract.md` \u00a7G2.\n\nSe construye **antes** de tener un candidato positivo, a prop\u00f3sito: escribir el\ntest estad\u00edstico despu\u00e9s de ver un resultado bueno invita a ajustarlo hasta que\nlo apruebe. Ac\u00e1 los umbrales vienen del contrato sellado y las funciones se\nverifican contra datos sint\u00e9ticos con verdad conocida.\n\n## Enmienda G2-A1 (2026-08-10) \u2014 leer antes de usar este m\u00f3dulo\n\nAuditor\u00eda adversarial encontr\u00f3 que `mcpt()`, tal como estaba, **contradice a\nG1**: G1 exige que ning\u00fan subperiodo aporte >80% del P&L (estabilidad); el\nestad\u00edstico real de la permutaci\u00f3n de bloques \u2014pese a lo que dec\u00eda su\ndocstring\u2014 no es la suma neta, es la concentraci\u00f3n temporal del P&L. Un edge\nque satisface G1 (P&L parejo en el tiempo) da, por construcci\u00f3n,\n`obs \u2248 total/2 \u2248 media de la permutaci\u00f3n`, o sea `p \u2248 0.5` y **FAIL**. El gate\npremiaba al edge que decae y bloqueaba al que se sostiene \u2014 exactamente lo\nopuesto de lo que el proyecto busca. Detalle completo:\n`docs/incidents/AMENDMENT_G2-A1_2026-08-10.md`.\n\nCambios de esta enmienda, aprobada por Nico el 2026-08-10:\n\n1. `mcpt()` \u2192 renombrada `temporal_concentration_test()`, y **sacada de los\n   gates duros**. Sigue siendo \u00fatil como diagn\u00f3stico \u2014detecta EN QU\u00c9 MITAD se\n   concentra el resultado\u2014, pero no decide aprobar/rechazar.\n2. El gate que reemplaza su rol es el que ya exist\u00eda y nunca se usaba como\n   tal: `g2_decision.PrimaryCI`, bootstrap estacionario-t por sesi\u00f3n con\n   `lower > 0`. Es la MISMA m\u00e1quina de inferencia que us\u00f3 H1\n   (`edgelab.stats.cluster_estimand.studentized_stationary_interval`).\n3. El umbral DSR se unifica en **0,95** (antes: `g2.py` ten\u00eda `> 0`, vacuo \u2014\n   pasa con puro ruido\u2014, y `g2_decision.py` ten\u00eda un allowlist vac\u00edo \u2014nunca\n   aprueba nada\u2014. Dos definiciones contradictorias de \"G2 aprobado\" en el\n   mismo repo).\n4. `AUTHORIZED_DSR_METHOD_SHA256S` se puebla con el hash real del m\u00e9todo\n   (`dsr_method_sha256()` abajo), no queda vac\u00edo.\n5. `evaluar()` \u2014la ruta vacua, cuyo \u00fanico poder discriminante real era \"hubo\n   al menos 2 observaciones\"\u2014 **se elimina**. Una sola definici\u00f3n ejecutable\n   de \"G2 aprobado\": `g2_decision.G2ValidationDecision.passed`.\n\nPruebas duras vigentes (\u00a7G2, tras la enmienda):\n\n1. `deflated_sharpe`  \u2014 DSR \u2265 0.95 con n\u00ba de trials = N_eff del manifiesto,\n   v\u00eda `g2_decision.DSREvidence` con m\u00e9todo autorizado.\n2. `PrimaryCI`        \u2014 bootstrap estacionario-t por sesi\u00f3n, `lower > 0`.\n3. `pbo_cscv`         \u2014 PBO \u2264 0.50 v\u00eda CSCV con S = 8.\n4. `walk_forward`     \u2014 re-selecci\u00f3n por contrato; agregado WF-OOS neto > 0.\n5. `parameter_sensitivity` \u2014 vecinos \u00b11 paso: mediana de expectancies netas > 0.\n\nSin dependencias nuevas: `statistics.NormalDist` (stdlib) cubre \u03a6 y \u03a6\u207b\u00b9.\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport inspect\nimport itertools\nimport math\nfrom statistics import NormalDist\n\n# --- umbrales DUROS del contrato (no se tocan sin enmienda aprobada) --------\nPBO_MAX = 0.50\nCSCV_S = 8\nTEMPORAL_CONCENTRATION_MIN_PERMS = 1000   # diagnostico, no gate -- ver enmienda G2-A1\n\n_N = NormalDist()\n_EULER = 0.5772156649015329\n\n\n# --------------------------------------------------------------------------- #\n# 1. Concentraci\u00f3n temporal \u2014 DIAGN\u00d3STICO, no gate (ver enmienda G2-A1)\n# --------------------------------------------------------------------------- #\ndef _lcg(seed):\n    \"\"\"Generador determinista propio: el resultado no puede depender de la\n    versi\u00f3n de numpy ni del estado global de random.\"\"\"\n    x = seed & 0xFFFFFFFF\n    while True:\n        x = (1664525 * x + 1013904223) & 0xFFFFFFFF\n        yield x\n\n\ndef _shuffle(seq, rng):\n    \"\"\"Fisher-Yates con el LCG: reproducible entre corridas y m\u00e1quinas.\"\"\"\n    a = list(seq)\n    for i in range(len(a) - 1, 0, -1):\n        j = next(rng) % (i + 1)\n        a[i], a[j] = a[j], a[i]\n    return a\n\n\ndef temporal_concentration_test(returns, session_ids,\n                                n_perm=TEMPORAL_CONCENTRATION_MIN_PERMS, seed=12345):\n    \"\"\"p-valor de CONCENTRACI\u00d3N TEMPORAL por permutaci\u00f3n de bloques de sesi\u00f3n.\n\n    **NO es un gate duro** (enmienda G2-A1, 2026-08-10) \u2014 antes se llamaba\n    `mcpt()` y se usaba como tal; el gate de robustez estad\u00edstica que\n    reemplaza su rol es `g2_decision.PrimaryCI`.\n\n    `returns[i]` es el neto del trade i y `session_ids[i]` su sesi\u00f3n. La\n    hip\u00f3tesis nula permuta el orden de las **sesiones completas**, no de los\n    trades individuales: eso preserva la autocorrelaci\u00f3n intrad\u00eda.\n\n    El estad\u00edstico **NO es la suma neta** \u2014eso no cambia bajo permutaci\u00f3n de\n    bloques, por construcci\u00f3n\u2014 es la suma de los primeros k bloques (la mitad\n    temporal): mide D\u00d3NDE se concentr\u00f3 el P&L, no SI hay P&L. Un p bajo dice\n    \"el resultado no est\u00e1 parejo en el tiempo\", que es informaci\u00f3n real, pero\n    es la pregunta de G1 (estabilidad) mirada desde el otro lado \u2014 no una\n    prueba de que la se\u00f1al informa. p = (1 + #{perm \u2265 observado}) / (1 + n_perm),\n    la forma sesgada-conservadora: nunca devuelve p = 0.\n    \"\"\"\n    if n_perm < TEMPORAL_CONCENTRATION_MIN_PERMS:\n        raise ValueError(\"el contrato exige >= %d permutaciones, no %d\"\n                         % (TEMPORAL_CONCENTRATION_MIN_PERMS, n_perm))\n    if len(returns) != len(session_ids):\n        raise ValueError(\"returns y session_ids deben tener el mismo largo\")\n    if not returns:\n        return 1.0, 0.0\n\n    bloques = {}\n    for r, s in zip(returns, session_ids):\n        bloques.setdefault(s, []).append(r)\n    claves = sorted(bloques)\n    if len(claves) < 2:\n        # Con una sola sesi\u00f3n no hay nada que permutar: se declara, no se finge.\n        return 1.0, float(sum(returns))\n\n    # Estad\u00edstico observado: suma de los k primeros bloques (la mitad\n    # temporal). Bajo permutaci\u00f3n de bloques la suma TOTAL no cambia -- por\n    # eso este estad\u00edstico mide concentraci\u00f3n, no presencia de efecto.\n    k = max(1, len(claves) // 2)\n    obs = sum(sum(bloques[c]) for c in claves[:k])\n\n    rng = _lcg(seed)\n    peores = 0\n    for _ in range(n_perm):\n        perm = _shuffle(claves, rng)\n        stat = sum(sum(bloques[c]) for c in perm[:k])\n        if stat >= obs:\n            peores += 1\n    return (1.0 + peores) / (1.0 + n_perm), float(obs)\n\n\n# --------------------------------------------------------------------------- #\n# 2. PBO v\u00eda CSCV\n# --------------------------------------------------------------------------- #\ndef pbo_cscv(matrix, s=CSCV_S):\n    \"\"\"Probability of Backtest Overfitting (Bailey et al.), CSCV con S bloques.\n\n    `matrix[t][c]` = performance del config `c` en el sub-per\u00edodo `t`.\n\n    Para cada partici\u00f3n del tiempo en mitad train / mitad test: se elige el mejor\n    config **in-sample** y se mide su **rango relativo out-of-sample**. Si el\n    ganador in-sample cae sistem\u00e1ticamente por debajo de la mediana OOS, el\n    procedimiento de selecci\u00f3n est\u00e1 sobreajustando.\n\n    PBO = fracci\u00f3n de particiones con logit \u03bb \u2264 0.\n    \"\"\"\n    T = len(matrix)\n    if T < s:\n        raise ValueError(\"hacen falta al menos S=%d filas de tiempo, hay %d\" % (s, T))\n    n_cfg = len(matrix[0])\n    if n_cfg < 2:\n        raise ValueError(\"PBO necesita al menos 2 configs para rankear\")\n\n    corte = [round(i * T / s) for i in range(s + 1)]\n    bloques = [list(range(corte[i], corte[i + 1])) for i in range(s)]\n\n    lambdas = []\n    for comb in itertools.combinations(range(s), s // 2):\n        tr = [i for b in comb for i in bloques[b]]\n        te = [i for b in range(s) if b not in comb for i in bloques[b]]\n        if not tr or not te:\n            continue\n        perf_tr = [sum(matrix[t][c] for t in tr) for c in range(n_cfg)]\n        perf_te = [sum(matrix[t][c] for t in te) for c in range(n_cfg)]\n        best = max(range(n_cfg), key=lambda c: perf_tr[c])\n        # rango relativo OOS del ganador in-sample (1 = el mejor)\n        orden = sorted(range(n_cfg), key=lambda c: perf_te[c])\n        rango = orden.index(best) + 1\n        w = rango / (n_cfg + 1.0)\n        w = min(max(w, 1e-9), 1 - 1e-9)\n        lambdas.append(math.log(w / (1 - w)))\n\n    if not lambdas:\n        raise ValueError(\"no se generaron particiones CSCV\")\n    pbo = sum(1 for x in lambdas if x <= 0) / len(lambdas)\n    return pbo, lambdas\n\n\n# --------------------------------------------------------------------------- #\n# 3. Deflated Sharpe Ratio\n# --------------------------------------------------------------------------- #\ndef expected_max_sharpe(n_trials, var_sharpe):\n    \"\"\"SR esperado del MEJOR de `n_trials` intentos bajo la nula (Bailey/LdP).\"\"\"\n    if n_trials < 2:\n        return 0.0\n    sd = math.sqrt(max(var_sharpe, 0.0))\n    a = _N.inv_cdf(1 - 1.0 / n_trials)\n    b = _N.inv_cdf(1 - 1.0 / (n_trials * math.e))\n    return sd * ((1 - _EULER) * a + _EULER * b)\n\n\ndef deflated_sharpe(sharpe, n_obs, n_trials, skew=0.0, kurt=3.0,\n                    var_sharpe=None):\n    \"\"\"DSR: probabilidad de que el Sharpe observado supere al esperado por azar\n    tras cobrar **todas** las variantes probadas (`n_trials` = N_eff, \u00a7G2).\n\n    Corrige por el n\u00famero de intentos y por los momentos de orden superior: una\n    estrategia con cola izquierda gruesa necesita m\u00e1s Sharpe para el mismo DSR.\n    \"\"\"\n    if n_obs < 2:\n        return 0.0\n    if var_sharpe is None:\n        # varianza del estimador de Sharpe bajo no-normalidad\n        var_sharpe = (1 - skew * sharpe + (kurt - 1) / 4.0 * sharpe ** 2) / (n_obs - 1)\n    sr0 = expected_max_sharpe(n_trials, var_sharpe)\n    den = math.sqrt(max(var_sharpe, 1e-18))\n    return _N.cdf((sharpe - sr0) / den)\n\n\ndef dsr_method_sha256():\n    \"\"\"sha256 del M\u00c9TODO de c\u00f3mputo del DSR (`deflated_sharpe` +\n    `expected_max_sharpe`), no de un resultado.\n\n    `g2_decision.AUTHORIZED_DSR_METHOD_SHA256S` exige que el `method_sha256`\n    declarado en cada `DSREvidence` coincida con esto \u2014 as\u00ed, cambiar la\n    f\u00f3rmula del DSR sin pasar por ac\u00e1 invalida autom\u00e1ticamente cualquier\n    decisi\u00f3n que dependa de la versi\u00f3n vieja, en vez de aprobar en silencio\n    con matem\u00e1tica distinta a la auditada. Mismo principio que\n    `curva_excursion_ticks.huella_del_codigo`: hashear las fuentes que pueden\n    mover el n\u00famero, no confiar en que \"no cambi\u00f3 nada importante\".\n    \"\"\"\n    fuente = inspect.getsource(deflated_sharpe) + inspect.getsource(expected_max_sharpe)\n    return hashlib.sha256(fuente.encode(\"utf-8\")).hexdigest()\n\n\n# --------------------------------------------------------------------------- #\n# 4. Walk-forward por contrato\n# --------------------------------------------------------------------------- #\ndef walk_forward(per_fold, folds_ordenados, seleccionar=None):\n    \"\"\"WF-OOS por contrato (\u00a7G2).\n\n    `per_fold[config][fold]` = neto de ese config en ese fold. Para cada fold `k`\n    (k \u2265 1) se re-elige el ganador usando **s\u00f3lo** los folds anteriores y se\n    eval\u00faa en `k`. El fold 0 no es evaluable: no tiene historia previa.\n\n    Devuelve (agregado_oos, detalle_por_fold).\n    \"\"\"\n    if seleccionar is None:\n        def seleccionar(cands):\n            return max(cands, key=lambda kv: kv[1])[0]\n\n    detalle, total = [], 0.0\n    for i in range(1, len(folds_ordenados)):\n        prev = folds_ordenados[:i]\n        test = folds_ordenados[i]\n        cands = [(c, sum(per_fold[c].get(f, 0.0) for f in prev)) for c in per_fold]\n        gan = seleccionar(cands)\n        oos = per_fold[gan].get(test, 0.0)\n        total += oos\n        detalle.append(dict(fold=test, ganador_in_sample=gan, oos_neto=oos,\n                            entrenado_con=list(prev)))\n    return total, detalle\n\n\n# --------------------------------------------------------------------------- #\n# 5. Sensibilidad param\u00e9trica\n# --------------------------------------------------------------------------- #\ndef parameter_sensitivity(expectancies, ganador, vecinos):\n    \"\"\"Mediana de las expectancies netas de los vecinos \u00b11 paso de grilla (\u00a7G2).\n\n    Un ganador rodeado de vecinos negativos es un pico aislado \u2014 la firma de un\n    acantilado de sobreajuste, no de un efecto real.\n    \"\"\"\n    vals = [expectancies[v] for v in vecinos if v in expectancies]\n    if not vals:\n        return None, 0, 0\n    vals.sort()\n    n = len(vals)\n    mediana = vals[n // 2] if n % 2 else (vals[n // 2 - 1] + vals[n // 2]) / 2.0\n    return mediana, sum(1 for v in vals if v > 0), n\n\n# NOTA (enmienda G2-A1, 2026-08-10): exist\u00eda ac\u00e1 una funci\u00f3n `evaluar()` que\n# ofrec\u00eda una segunda definici\u00f3n de \"G2 aprobado\", con un umbral de DSR vacuo\n# (`> 0`, aprobaba con puro ruido) contradictorio con el umbral real de\n# `g2_decision.py` (`>= 0.95`). Eliminada \u2014 la \u00fanica definici\u00f3n ejecutable de\n# \"G2 aprobado\" es `g2_decision.G2ValidationDecision.passed`. Ver\n# `docs/incidents/AMENDMENT_G2-A1_2026-08-10.md`.\n", "edgelab/__init__.py": "", "edgelab/research/__init__.py": "", "edgelab/funnel/__init__.py": ""}
